-- =============================================================================
-- 523 — LE CAHIER D'EXERCICES DE 1RE (partie 11)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 523 --niveau 1re --fichiers espagnol.n1,francais.n10a,francais.n10b,francais.n11a --suffixe 11 > supabase/contenu/523_exercices_1re_11.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   espagnol.n1             36 exercices · 12 chapitres
--   francais.n10a           18 exercices · 6 chapitres
--   francais.n10b           18 exercices · 6 chapitres
--   francais.n11a           18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('13a67dee-6447-5277-a6c8-01df0d0d56d2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un voyage en moto à travers l’Amérique du Sud","competence":"analyser-texte","situation":"Pour son club de cinéma, Daniela lit la présentation d’un film sur un grand voyage. Elle relève les informations essentielles.","documents":[{"id":"nota","type":"texte","genre":"article","titre":"Una película sobre un viaje","blocs":["En 1952, un joven argentino, Ernesto Guevara, recorre América del Sur en motocicleta. Al principio busca la aventura, pero poco a poco descubre la pobreza y la injusticia que viven muchas personas.","En 2004, el director Walter Salles cuenta ese viaje en la película *Diarios de motocicleta*."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’**année** où commence le voyage de Guevara.","aide":"Elle est donnée au début du premier paragraphe ; l’autre date du texte est celle du film.","type":"zone","document":"nota","multiple":false},{"enonce":"Touche le **nom du réalisateur** du film.","aide":"Cherche « el director » dans le second paragraphe : son nom vient juste après.","type":"zone","document":"nota","multiple":true},{"enonce":"Que découvre le jeune voyageur au fil du chemin ?","aide":"Relis la fin de la première phrase : « poco a poco descubre… ».","type":"choix","options":[{"id":"a","texte":"Les lois de la physique des montagnes"},{"id":"b","texte":"Le goût du tourisme organisé en groupe"},{"id":"c","texte":"Les palaces des grandes capitales du continent"},{"id":"d","texte":"La pauvreté et l’injustice vécues par beaucoup de gens"}],"multiple":false},{"enonce":"Associe chaque mot du vocabulaire du voyage et de la migration à sa traduction.","aide":"Pars du mot que tu reconnais : *frontera*, *papeles*.","type":"association","gauche":[{"id":"g0","texte":"cruzar la frontera"},{"id":"g1","texte":"el país de acogida"},{"id":"g2","texte":"echar de menos"},{"id":"g3","texte":"sin papeles"}],"droite":[{"id":"d0","texte":"avoir le mal du pays"},{"id":"d1","texte":"sans papiers"},{"id":"d2","texte":"le pays d’accueil"},{"id":"d3","texte":"passer la frontière"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**1952** : c’est l’année du voyage. 2004 est l’année où le film a été tourné, bien plus tard."},{"cle":{"type":"zone","ids":["m36","m37"]},"explication":"**Walter Salles** a réalisé *Diarios de motocicleta* en 2004."},{"cle":{"type":"choix","ids":["d"]},"explication":"**La pauvreté et l’injustice** : le voyage lui fait découvrir l’autre, et c’est ce qui change son regard."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"*Cruzar la frontera* = **passer la frontière** ; *el país de acogida* = **le pays d’accueil** ; *echar de menos* = **regretter, avoir le mal du pays** ; *sin papeles* = **sans papiers**."}]$ex$::jsonb),
  ('13a67dee-6447-5277-a6c8-01df0d0d56d2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une frise pour l’exposé de Lucía","competence":"se-reperer-temps","situation":"Lucía prépare un exposé sur les départs dans le monde hispanique. Elle a placé quelques repères sur une frise et doit les exploiter.","documents":[{"id":"frisa","type":"frise","titre":"Partir : quelques repères","debut":1930,"fin":2030,"pas":10,"periodes":[{"id":"z1","debut":1960,"fin":1969,"nom":"Années 1960","teinte":"ambre"}],"evenements":[{"id":"z2","date":1939,"nom":"Retirada"},{"id":"z3","date":1952,"nom":"Voyage de Guevara"},{"id":"z4","date":1998,"nom":"Clandestino"},{"id":"z5","date":2013,"nom":"La jaula de oro"},{"id":"z6","date":2015,"nom":"Exode vénézuélien"}],"source":"Frise réalisée pour l’exercice"}],"questions":[{"enonce":"Dans les années 1960, beaucoup d’Espagnols partent travailler en France, en Allemagne ou en Suisse. Touche la **période** de la frise qui correspond.","aide":"Une période est une bande colorée, pas un point : cherche la décennie annoncée.","type":"zone","document":"frisa","multiple":false},{"enonce":"Combien d’**années** séparent la Retirada du voyage de Guevara ?","aide":"Soustrais la date de la Retirada à celle du voyage.","type":"nombre","unite":"ans"},{"enonce":"Quel repère est un film de 2013 qui suit des migrants d’Amérique centrale grimpés sur le train *La Bestia* ? Touche-le.","aide":"Son titre signifie « la cage dorée ».","type":"zone","document":"frisa","multiple":false},{"enonce":"Complète la phrase sur la Retirada.","aide":"Après *tuvieron que*, le verbe est à l’infinitif.","type":"trous","segments":["En 1939, los republicanos tuvieron que ",0," la frontera."],"banque":["cruzar","cruzando","cruzado","cruzaron"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Les années 1960** : c’est la décennie de l’émigration espagnole vers l’Europe du Nord et de l’Ouest."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 ans","explication":"1952 − 1939 = **13 ans**."},{"cle":{"type":"zone","ids":["z5"]},"explication":"***La jaula de oro*** (2013) : le film de Diego Quemada-Díez montre le voyage de ces migrants vers les États-Unis."},{"cle":{"type":"trous","trous":[["cruzar"]]},"affichage":"cruzar","explication":"**tuvieron que cruzar** : *tener que* + infinitif exprime l’obligation. *Cruzar la frontera* = passer la frontière."}]$ex$::jsonb),
  ('13a67dee-6447-5277-a6c8-01df0d0d56d2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le mur de Tijuana : barrière ou lieu de rencontre ?","competence":"argumenter","situation":"Pour son oral, Mateo doit répondre à la question « ¿Las fronteras separan o unen? ». Il étudie un article sur le mur de Tijuana et la carte de la région.","documents":[{"id":"mapa","type":"carte","titre":"L’Amérique du Nord","fond":"monde","cadrage":[-125,13,-70,50],"regionsCliquables":true,"lieux":[{"id":"z1","lon":-117.04,"lat":32.51,"nom":"Tijuana","symbole":"point"}],"source":"Fond de carte simplifié"},{"id":"muro","type":"texte","genre":"article","titre":"El muro de Tijuana","blocs":["En Tijuana, el muro entre México y Estados Unidos baja hasta el océano Pacífico. La frontera mide unos 3 100 kilómetros y está cerrada en parte por un muro.","Muchos migrantes de América Central viajan sobre *La Bestia*, un tren de mercancías, para llegar hasta allí. Por un lado, el muro protege un territorio; por otro lado, separa familias."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche sur la carte le **pays** où se trouve la ville de Tijuana et que traverse *La Bestia*.","aide":"Tijuana est au sud de la frontière, près de la côte Pacifique.","type":"zone","document":"mapa","multiple":false},{"enonce":"Un marcheur longerait la frontière en parcourant 25 km par jour. En combien de **jours** en viendrait-il à bout ?","aide":"Divise la longueur de la frontière, donnée dans l’article, par 25.","type":"nombre","unite":"jours"},{"enonce":"Remets en ordre la phrase qui **pose le problème** (« Il faut se demander si un mur peut arrêter celui qui fuit la pauvreté »). Elle commence par *Cabe preguntarse si*.","aide":"Sujet (un muro), puis le verbe, puis le complément de personne.","type":"ordre","items":[{"id":"a","texte":"puede frenar"},{"id":"b","texte":"Cabe preguntarse si"},{"id":"c","texte":"un muro"},{"id":"d","texte":"a quien huye de la pobreza"}]},{"enonce":"Complète la phrase qui explique une cause.","aide":"Il faut un connecteur de cause qui se place après la proposition principale.","type":"trous","segments":["Muchos emigran ",0," no encuentran trabajo en su país."],"banque":["como","porque","pero","aunque"]},{"enonce":"Quelle phrase pourrait servir de **conclusion** (*En definitiva…*) à l’oral de Mateo ?","aide":"L’article montre deux effets opposés du mur : choisis la phrase qui les réunit.","type":"choix","options":[{"id":"a","texte":"En definitiva, la frontera es tanto una barrera como un lugar de encuentro."},{"id":"b","texte":"En definitiva, ninguna familia vive a los dos lados de la frontera."},{"id":"c","texte":"En definitiva, los muros resuelven todos los problemas de los migrantes."},{"id":"d","texte":"En definitiva, la frontera es solo una línea sin importancia para nadie."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["MEX"]},"explication":"**Le Mexique** : Tijuana est sa ville frontière, tout au nord-ouest du pays, face aux États-Unis."},{"cle":{"type":"nombre","valeur":124,"tolerance":0},"affichage":"124 jours","explication":"3 100 ÷ 25 = **124 jours** : plus de quatre mois de marche, ce qui donne la mesure de cette frontière."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"**Cabe preguntarse si un muro puede frenar a quien huye de la pobreza** : *cabe preguntarse si…* est la formule pour poser le problème."},{"cle":{"type":"trous","trous":[["porque"]]},"affichage":"porque","explication":"**porque** : il introduit la cause, après la principale. *Como* se place en tête de phrase et *aunque* exprime une concession."},{"cle":{"type":"choix","ids":["a"]},"explication":"**La frontière est à la fois une barrière et un lieu de rencontre** : le mur protège d’un côté, sépare des familles de l’autre, et c’est cette ambivalence que l’oral doit montrer."}]$ex$::jsonb),
  ('7dee57c7-9d68-59ca-a19d-6c141d826104'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’affiche de Campeones","competence":"analyser-document","situation":"Samuel hésite à voir un film avec ses amis. Il lit l’affiche de *Campeones* à la sortie du cinéma.","documents":[{"id":"cartel","type":"fiche","modele":"affiche","entete":"CAMPEONES","sousTitre":"Una película sobre la igualdad","emoji":"🏀","lignes":[{"texte":"Dirección","valeur":"Javier Fesser","id":"z1"},{"texte":"Año","valeur":"2018","id":"z2"},{"separateur":true},{"texte":"Un entrenador de baloncesto debe dirigir un equipo de jugadores con discapacidad intelectual.","id":"z3"},{"separateur":true},{"texte":"Goya a la mejor película","gras":true,"id":"z4"}],"pied":"En todos los cines","teinte":"violet","source":"Affiche reconstituée pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui donne le **nom du réalisateur**.","aide":"*Dirección* indique qui dirige le film.","type":"zone","document":"cartel","multiple":false},{"enonce":"Touche la ligne qui annonce la **récompense** reçue par le film.","aide":"Un Goya est le grand prix du cinéma espagnol.","type":"zone","document":"cartel","multiple":false},{"enonce":"Complète la phrase qui résume le sujet du film.","aide":"Le mot veut dire « handicap » ; il est écrit sur l’affiche.","type":"trous","segments":["Los jugadores tienen una ",0," intelectual."],"banque":["discapacidad","minoría","convivencia","discriminación"]},{"enonce":"Associe chaque mot de l’inclusion à sa traduction.","aide":"Ces mots ressemblent aux mots français correspondants, sauf un.","type":"association","gauche":[{"id":"g0","texte":"la discapacidad"},{"id":"g1","texte":"la igualdad de derechos"},{"id":"g2","texte":"la convivencia"},{"id":"g3","texte":"la discriminación"}],"droite":[{"id":"d0","texte":"la discrimination"},{"id":"d1","texte":"l’égalité des droits"},{"id":"d2","texte":"le handicap"},{"id":"d3","texte":"le vivre-ensemble"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Javier Fesser** : *la dirección* est la mise en scène, donc le réalisateur du film."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**Goya a la mejor película** : le film a reçu le prix du meilleur film."},{"cle":{"type":"trous","trous":[["discapacidad"]]},"affichage":"discapacidad","explication":"**discapacidad** : *la discapacidad* = le handicap. Une *minoría* est un groupe moins nombreux, pas une situation de santé."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"*Discapacidad* = **handicap** ; *igualdad de derechos* = **égalité des droits** ; *convivencia* = **vivre-ensemble** ; *discriminación* = **discrimination**."}]$ex$::jsonb),
  ('7dee57c7-9d68-59ca-a19d-6c141d826104'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Quelles langues parle-t-on dans ces pays ?","competence":"lire-tableau","situation":"Jade prépare une présentation sur la pluralité linguistique. Elle a rassemblé un tableau, qu’elle commente à l’oral.","documents":[{"id":"lenguas","type":"tableau","titre":"Las lenguas en cinco países","colonnes":["País","Lenguas","Ejemplos de lenguas minoritarias"],"lignes":[["España","castellano y lenguas cooficiales","catalán, euskera, gallego"],["México","español y 68 lenguas indígenas","náhuatl"],["Perú","español y lenguas indígenas","quechua, aimara"],["Bolivia","español y lenguas indígenas","quechua, aimara"],["Paraguay","español y guaraní","guaraní"]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Touche la **case** qui donne le nombre de langues autochtones du Mexique.","aide":"Cherche la ligne *México*, puis la colonne *Lenguas*.","type":"zone","document":"lenguas","multiple":false},{"enonce":"Combien de langues autochtones le tableau cite-t-il pour le Mexique ?","aide":"Le nombre est écrit dans la même case.","type":"nombre"},{"enonce":"Touche le **pays** où l’espagnol partage son statut avec le guarani.","aide":"Repère le mot *guaraní* dans la colonne des langues.","type":"zone","document":"lenguas","multiple":false},{"enonce":"Complète la phrase pour demander un changement.","aide":"Après *es necesario que*, on emploie le subjonctif.","type":"trous","segments":["Es necesario que las lenguas indígenas se ",0," en la escuela."],"banque":["enseñen","enseñar","enseñan","enseñarán"]},{"enonce":"Associe chaque langue au peuple ou au pays où elle est parlée.","aide":"Le tableau donne une partie des couples ; le náhuatl est la langue des Aztèques.","type":"association","gauche":[{"id":"g0","texte":"el náhuatl"},{"id":"g1","texte":"el quechua"},{"id":"g2","texte":"el guaraní"},{"id":"g3","texte":"el euskera"}],"droite":[{"id":"d0","texte":"le Paraguay"},{"id":"d1","texte":"les Aztèques au Mexique"},{"id":"d2","texte":"le Pays basque, en Espagne"},{"id":"d3","texte":"les Andes, au Pérou et en Bolivie"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**« español y 68 lenguas indígenas »** : le Mexique reconnaît 68 langues autochtones comme langues nationales."},{"cle":{"type":"nombre","valeur":68,"tolerance":0},"affichage":"68","explication":"**68** langues autochtones reconnues comme langues nationales, dont le nahuatl, la langue des Aztèques."},{"cle":{"type":"zone","ids":["r4c0"]},"explication":"**Le Paraguay** : l’espagnol et le guarani y sont tous deux officiels."},{"cle":{"type":"trous","trous":[["ensenen"]]},"affichage":"enseñen","explication":"**se enseñen** : *es necesario que* est suivi du subjonctif présent (*enseñan* est l’indicatif)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"*Náhuatl* : **les Aztèques** ; *quechua* : **les Andes** ; *guaraní* : **le Paraguay** ; *euskera* : **le Pays basque**."}]$ex$::jsonb),
  ('7dee57c7-9d68-59ca-a19d-6c141d826104'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Menchú et Morales : deux voix autochtones","competence":"analyser-document","situation":"Dans un exposé sur les minorités, Nuria et Álex se partagent deux figures des peuples autochtones. Ils échangent des messages pour croiser leurs notes.","documents":[{"id":"perfil","type":"texte","genre":"article","titre":"Una voz maya","blocs":["Rigoberta Menchú nació en Guatemala. Es una militante maya k’iche’ que defiende los derechos de los pueblos indígenas.","En 1992 recibió el Premio Nobel de la Paz."],"source":"Fiche écrite pour l’exercice"},{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Nuria et d’Álex","participants":[{"nom":"Nuria","emoji":"👧","cote":"gauche"},{"nom":"Álex","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nuria","texte":"Hoy hemos hablado de Bolivia: es un Estado plurinacional."},{"qui":"Álex","texte":"Sí, desde la Constitución de 2009, que reconoce las lenguas de los pueblos indígenas."},{"qui":"Álex","texte":"Evo Morales, que es aimara, fue presidente de 2006 a 2019."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’**année** de la Constitution qui fait de la Bolivie un État plurinational.","aide":"Álex la donne dans son premier message.","type":"zone","document":"chat","multiple":false},{"enonce":"Combien d’**années** séparent le prix Nobel de Rigoberta Menchú de la Constitution bolivienne ?","aide":"Une date vient de la fiche, l’autre des messages.","type":"nombre","unite":"ans"},{"enonce":"Range chaque information dans le bon pays.","aide":"La fiche parle d’un seul pays, les messages de l’autre.","type":"categories","categories":[{"id":"c0","texte":"Guatemala"},{"id":"c1","texte":"Bolivia"}],"items":[{"id":"i0","texte":"Rigoberta Menchú"},{"id":"i1","texte":"Evo Morales"},{"id":"i2","texte":"un Estado plurinacional"},{"id":"i3","texte":"una militante maya k’iche’"},{"id":"i4","texte":"Premio Nobel de la Paz, 1992"},{"id":"i5","texte":"Constitución de 2009"}]},{"enonce":"¿Qué presidente boliviano es de origen aimara?","aide":"Álex le dit dans le dernier message : il a gouverné de 2006 à 2019.","type":"choix","options":[{"id":"a","texte":"Javier Fesser"},{"id":"b","texte":"Evo Morales"},{"id":"c","texte":"Rigoberta Menchú"},{"id":"d","texte":"Simón Bolívar"}],"multiple":false},{"enonce":"Complète la phrase qui dénonce.","aide":"Après *es inadmisible que*, on emploie le subjonctif.","type":"trous","segments":["Es inadmisible que se ",0," a las personas por su origen."],"banque":["discrimine","discriminar","discrimina","discriminará"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**2009** : la Constitution de 2009 reconnaît les langues des peuples autochtones. 2006 et 2019 sont les dates du mandat d’Evo Morales."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17 ans","explication":"2009 − 1992 = **17 ans**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Menchú, son Nobel de 1992 et son origine maya renvoient au **Guatemala** ; Morales, la Constitution de 2009 et l’État plurinational à la **Bolivie**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Evo Morales**, d’origine aymara, a été président de la Bolivie de 2006 à 2019. Menchú est une militante guatémaltèque."},{"cle":{"type":"trous","trous":[["discrimine"]]},"affichage":"discrimine","explication":"**se discrimine** : *es inadmisible que* + subjonctif présent pour dénoncer une situation."}]$ex$::jsonb),
  ('63dfa6e8-7f5c-5110-a2d9-6c6534e421a0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le peintre du roi Philippe IV","competence":"analyser-texte","situation":"Au musée du Prado, Elena lit le panneau qui accompagne un grand tableau d’histoire peint pour un roi.","documents":[{"id":"panel","type":"texte","genre":"article","titre":"Panel del museo","blocs":["Diego Velázquez es el pintor del rey Felipe IV, en el siglo XVII. Recibe del rey un encargo: pintar una victoria del ejército español.","Pinta *La rendición de Breda* en 1635. Este cuadro glorifica la monarquía."],"source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **nom du roi** pour qui travaille Velázquez.","aide":"C’est un nom suivi d’un chiffre romain, dans la première phrase.","type":"zone","document":"panel","multiple":true},{"enonce":"Touche l’**année** où il peint *La rendición de Breda*.","aide":"Un seul nombre de quatre chiffres figure dans le second paragraphe.","type":"zone","document":"panel","multiple":false},{"enonce":"Quel rôle ce tableau joue-t-il pour le pouvoir ?","aide":"Relis la dernière phrase du panneau.","type":"choix","options":[{"id":"a","texte":"Il cache la guerre au peuple"},{"id":"b","texte":"Il critique la monarquía"},{"id":"c","texte":"Il raconte la Révolution mexicaine"},{"id":"d","texte":"Il glorifie la monarquía"}],"multiple":false},{"enonce":"Associe chaque mot du vocabulaire de l’art et du pouvoir à sa traduction.","aide":"Le panneau emploie *encargo* : il te donne la première paire.","type":"association","gauche":[{"id":"g0","texte":"el encargo"},{"id":"g1","texte":"la censura"},{"id":"g2","texte":"comprometido"},{"id":"g3","texte":"denunciar"}],"droite":[{"id":"d0","texte":"dénoncer"},{"id":"d1","texte":"la commande"},{"id":"d2","texte":"la censure"},{"id":"d3","texte":"engagé"}]}]}$ex$::jsonb,
