   $ex${"titre":"Des serres d’Almería aux lagunes qui se vident","competence":"argumenter","situation":"Pour un débat, Carmen cherche à expliquer qui paie le prix de la surexploitation de l’eau. Elle croise un article sur Almería et la Catalogne et une chaîne de causes.","documents":[{"id":"cadena","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Más invernaderos","emoji":"🏭"},{"id":"z2","texte":"Más agua bombeada","emoji":"💧"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Lagunas secas","emoji":"🏜️"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}],"source":"Chaîne imaginée pour l’exercice"},{"id":"prensa","type":"texte","genre":"article","titre":"Sequía y cultivos","blocs":["Alrededor de Almería, miles de invernaderos producen frutas y verduras todo el año. Pero necesitan mucha agua.","En 2024, los embalses de Cataluña alcanzaron su nivel más bajo: hay sequía y los recursos naturales se agotan."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’**année** où les réservoirs de Catalogne atteignent leur niveau le plus bas.","aide":"Elle est dans le second paragraphe.","type":"zone","document":"prensa","multiple":false},{"enonce":"Quel maillon manque dans la chaîne (le « ? ») ?","aide":"Entre « on pompe plus d’eau » et « les lagunes sont sèches », qu’arrive-t-il aux réserves du sous-sol ?","type":"choix","options":[{"id":"a","texte":"Llueve mucho más"},{"id":"b","texte":"Los acuíferos se agotan"},{"id":"c","texte":"El agua es gratuita"},{"id":"d","texte":"Crece el bosque"}],"multiple":false},{"enonce":"Complète la phrase qui montre une conséquence.","aide":"Il faut un connecteur qui introduit la **conséquence** de ce qui précède.","type":"trous","segments":["Hay sequía; ",0,", los embalses están vacíos."],"banque":["aunque","por consiguiente","como","porque"]},{"enonce":"Associe chaque formule de l’oral à sa fonction.","aide":"Chaque formule a un sens très net : « il faudrait » propose, « par conséquent » conclut une cause.","type":"association","gauche":[{"id":"g0","texte":"Es urgente que…"},{"id":"g1","texte":"Por consiguiente…"},{"id":"g2","texte":"Convendría…"},{"id":"g3","texte":"Hay que matizar…"}],"droite":[{"id":"d0","texte":"relativiser"},{"id":"d1","texte":"montrer une conséquence"},{"id":"d2","texte":"proposer"},{"id":"d3","texte":"alerter"}]},{"enonce":"Quelle phrase formule une **proposition** cohérente avec les documents ?","aide":"La proposition doit agir sur la cause : le manque d’eau.","type":"choix","options":[{"id":"a","texte":"Convendría ignorar la sequía de los embalses."},{"id":"b","texte":"Convendría construir más invernaderos en las zonas secas."},{"id":"c","texte":"Convendría limitar los cultivos que consumen más agua."},{"id":"d","texte":"Convendría bombear más agua de los acuíferos."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**2024** : cette année-là, les réservoirs de Catalogne sont au plus bas."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Los acuíferos se agotan** : en pompant plus que la nature ne renouvelle, on épuise les nappes, et les lagunes qu’elles alimentent s’assèchent."},{"cle":{"type":"trous","trous":[["por consiguiente"]]},"affichage":"por consiguiente","explication":"**por consiguiente** = par conséquent : il introduit la conséquence. *Porque* et *como* introduisent une cause."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"*Es urgente que* **alerte** ; *por consiguiente* **montre une conséquence** ; *convendría* **propose** ; *hay que matizar* **relativise**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Limiter les cultures les plus gourmandes en eau** répond à la cause du problème : *convendría* + infinitif sert à proposer."}]$ex$::jsonb),
  ('e66bb08e-c67e-5e2c-a1c0-6544d0241007'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La cordillère des Andes en chiffres","competence":"analyser-texte","situation":"Marina prépare une fiche sur les Andes pour son cours d’espagnol. Elle relève les repères dans un petit texte de présentation.","documents":[{"id":"ficha","type":"texte","genre":"article","titre":"Los Andes","blocs":["La cordillera de los Andes se extiende por siete países: Venezuela, Colombia, Ecuador, Perú, Bolivia, Chile y Argentina. Mide unos 7 000 kilómetros.","La cumbre más alta de América es el Aconcagua, en Argentina: tiene 6 961 metros. Entre Perú y Bolivia está el lago Titicaca, a más de 3 800 metros."],"source":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche le nom du **plus haut sommet** des Amériques.","aide":"Il se trouve en Argentine ; sa hauteur est donnée juste après.","type":"zone","document":"ficha","multiple":false},{"enonce":"Combien de **pays** la cordillère traverse-t-elle d’après le texte ? (Compte-les dans la première phrase.)","aide":"Compte les noms de pays séparés par des virgules.","type":"nombre"},{"enonce":"Entre quels pays se trouve le lac Titicaca ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Le Chili et l’Argentine"},{"id":"b","texte":"Le Pérou et la Bolivie"},{"id":"c","texte":"Le Venezuela et le Pérou"},{"id":"d","texte":"La Colombie et l’Équateur"}],"multiple":false},{"enonce":"Associe chaque mot du vocabulaire des montagnes à sa traduction.","aide":"La fiche emploie *cumbre* pour parler de l’Aconcagua.","type":"association","gauche":[{"id":"g0","texte":"la cordillera"},{"id":"g1","texte":"la cumbre"},{"id":"g2","texte":"el altiplano"},{"id":"g3","texte":"el glaciar"}],"droite":[{"id":"d0","texte":"le sommet"},{"id":"d1","texte":"le haut plateau"},{"id":"d2","texte":"le glacier"},{"id":"d3","texte":"la cordillère"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"**L’Aconcagua** : 6 961 m, en Argentine, c’est le plus haut sommet des Amériques."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"**7 pays** : Venezuela, Colombie, Équateur, Pérou, Bolivie, Chili, Argentine."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Entre le Pérou et la Bolivie** : le lac Titicaca est à plus de 3 800 mètres d’altitude."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*Cordillera* = **cordillère** ; *cumbre* = **sommet** ; *altiplano* = **haut plateau** ; *glaciar* = **glacier**."}]$ex$::jsonb),
  ('e66bb08e-c67e-5e2c-a1c0-6544d0241007'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Des Incas à Machu Picchu : une frise andine","competence":"se-reperer-temps","situation":"Sofía prépare un exposé sur l’héritage andin. Elle a placé sur une frise quelques dates qui relient l’histoire et le patrimoine.","documents":[{"id":"frisa","type":"frise","titre":"Les Andes, quelques repères","debut":1800,"fin":2025,"pas":25,"evenements":[{"id":"z1","date":1825,"nom":"Nom de la Bolivie"},{"id":"z2","date":1911,"nom":"Hiram Bingham"},{"id":"z3","date":1983,"nom":"Machu Picchu UNESCO"},{"id":"z4","date":2014,"nom":"Qhapaq Ñan UNESCO"}],"source":"Frise réalisée pour l’exercice"}],"questions":[{"enonce":"Quel repère correspond à l’explorateur qui a **révélé Machu Picchu au monde** ? Touche-le.","aide":"Cherche un nom de personne parmi les repères.","type":"zone","document":"frisa","multiple":false},{"enonce":"Combien d’**années** séparent la révélation de Machu Picchu de son inscription au patrimoine mondial ?","aide":"Lis les deux dates sur la frise : *Hiram Bingham* et *Machu Picchu UNESCO*.","type":"nombre","unite":"ans"},{"enonce":"Le Qhapaq Ñan est le réseau de chemins de l’Empire inca. Combien d’**années** après Machu Picchu a-t-il été inscrit à l’UNESCO ?","aide":"Compare les deux repères portant la mention UNESCO.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase sur la date de 1911.","aide":"C’est une action précise, datée de 1911 : on emploie le passé simple.","type":"trous","segments":["Hiram Bingham ",0," Machu Picchu al mundo en 1911."],"banque":["revelando","reveló","revelará","revelaba"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**1911** : Hiram Bingham fait connaître la cité inca de Machu Picchu au monde."},{"cle":{"type":"nombre","valeur":72,"tolerance":0},"affichage":"72 ans","explication":"1983 − 1911 = **72 ans**."},{"cle":{"type":"nombre","valeur":31,"tolerance":0},"affichage":"31 ans","explication":"2014 − 1983 = **31 ans**."},{"cle":{"type":"trous","trous":[["revelo"]]},"affichage":"reveló","explication":"**reveló** : l’indefinido (passé simple) exprime une action achevée à une date précise."}]$ex$::jsonb),
  ('e66bb08e-c67e-5e2c-a1c0-6544d0241007'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le triangle du lithium : richesse ou pillage ?","competence":"analyser-document","situation":"Dans un exposé sur les défis des Andes, Teo explique pourquoi une richesse du sous-sol peut devenir un problème. Il croise une carte et un article.","documents":[{"id":"mapa","type":"carte","titre":"L’Amérique du Sud","fond":"monde","cadrage":[-85,-57,-32,14],"regionsCliquables":true,"etiquettes":[{"texte":"Pérou","lon":-75,"lat":-9},{"texte":"Brésil","lon":-52,"lat":-10},{"texte":"Océan Pacifique","lon":-82,"lat":-25,"style":"mer"},{"texte":"Océan Atlantique","lon":-40,"lat":-35,"style":"mer"}],"source":"Fond de carte simplifié"},{"id":"litio","type":"texte","genre":"article","titre":"El triángulo del litio","blocs":["En el «triángulo del litio», formado por Bolivia, Chile y Argentina, se encuentra una gran parte de las reservas mundiales de este metal, que sirve para fabricar baterías.","Los salares atraen a las empresas, pero extraer litio consume mucha agua, un recurso escaso en el altiplano. Muchas comunidades campesinas temen quedarse sin ella."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche sur la carte les **trois pays** du « triangle du lithium » cités dans l’article.","aide":"Ils sont nommés dans la première phrase de l’article ; ils se suivent du nord au sud, côté Pacifique.","type":"zone","document":"mapa","multiple":true},{"enonce":"Touche le mot qui dit à **quoi sert** le lithium.","aide":"Pense à ce qui alimente un téléphone ou une voiture électrique.","type":"zone","document":"litio","multiple":false},{"enonce":"Complète la phrase qui souligne le paradoxe.","aide":"Il faut une expression qui oppose richesse et pauvreté.","type":"trous","segments":["Paradójicamente, ",0," sus riquezas, muchas comunidades siguen siendo pobres."],"banque":["debido a","a pesar de","gracias a","por eso"]},{"enonce":"Associe chaque défi andin à l’exemple qui lui correspond.","aide":"Pars de l’exemple que tu reconnais : le glacier bolivien disparu, le cuivre du Chili.","type":"association","gauche":[{"id":"g0","texte":"La minería"},{"id":"g1","texte":"El litio"},{"id":"g2","texte":"Los glaciares"},{"id":"g3","texte":"El buen vivir"}],"droite":[{"id":"d0","texte":"El triángulo Bolivia, Chile y Argentina"},{"id":"d1","texte":"Chacaltaya, desaparecido hacia 2009"},{"id":"d2","texte":"Vivir en armonía con la comunidad y la naturaleza"},{"id":"d3","texte":"Chile, primer productor mundial de cobre"}]},{"enonce":"Quelle phrase d’avenir respecte l’esprit du *buen vivir* ?","aide":"Le *buen vivir* cherche l’harmonie avec la communauté et la nature.","type":"choix","options":[{"id":"a","texte":"Será necesario que se olvide el uso del litio en las baterías."},{"id":"b","texte":"Será necesario que las comunidades abandonen el altiplano."},{"id":"c","texte":"Será necesario que la explotación respete el agua y a las comunidades."},{"id":"d","texte":"Será necesario que la explotación use toda el agua de los salares."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["BOL","CHL","ARG"]},"explication":"**La Bolivie, le Chili et l’Argentine** forment le triangle du lithium, qui concentre une grande part des réserves mondiales."},{"cle":{"type":"zone","ids":["m27"]},"explication":"**las baterías** : le lithium sert à fabriquer les batteries."},{"cle":{"type":"trous","trous":[["a pesar de"]]},"affichage":"a pesar de","explication":"**a pesar de** = malgré : il marque l’opposition, d’où le paradoxe. *Gracias a* exprimerait une cause heureuse."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*Minería* : **le cuivre chilien** ; *litio* : **le triangle Bolivie-Chili-Argentine** ; *glaciares* : **Chacaltaya** ; *buen vivir* : **l’harmonie avec la communauté et la nature**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Que l’exploitation respecte l’eau et les communautés** : c’est l’équilibre que cherche le *buen vivir*, avec *será necesario que* + subjonctif pour envisager l’avenir."}]$ex$::jsonb),
  ('0cccb5bd-e926-5645-98be-20330f76818b'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Du passé simple à l’imparfait du subjonctif","competence":"manier-langue","situation":"Pour son cahier de grammaire, Bruno a recopié un tableau qui part du passé simple pour retrouver l’imparfait du subjonctif. Certaines cases sont restées vides.","documents":[{"id":"tabla","type":"tableau","titre":"La base du subjuntivo","colonnes":["Infinitivo","Pretérito (ellos)","Imperfecto de subjuntivo (yo)"],"lignes":[["hablar","hablaron","hablara"],["comer","comieron","?"],["tener","tuvieron","tuviera"],["hacer","hicieron","?"]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Touche la **base** du passé simple (3e personne du pluriel) de *tener*.","aide":"Cherche la ligne *tener*, puis la colonne du pretérito.","type":"zone","document":"tabla","multiple":false},{"enonce":"Complète la case vide de la ligne *comer* : écris l’imparfait du subjonctif (yo), en **-ra**.","aide":"Retire *-ron* de *comieron* : il reste *comie-*, puis ajoute la terminaison de *yo*.","type":"texte"},{"enonce":"Complète la case vide de la ligne *hacer* : écris l’imparfait du subjonctif (yo), en **-ra**.","aide":"La base vient de *hicieron* ; garde bien le *c*.","type":"texte"},{"enonce":"Complète la phrase en la mettant au passé.","aide":"Passé simple de *poner* (ellos) : *pusieron*.","type":"trous","segments":["Mi madre quería que yo ",0," la mesa."],"banque":["pondría","pusiera","puse","ponga"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**tuvieron** : on retire *-ron* pour obtenir la base *tuvie-*, puis on ajoute *-ra*."},{"cle":{"type":"texte","acceptes":["comiera"]},"affichage":"comiera","explication":"**comiera** : *comieron* − *-ron* = *comie-*, plus *-ra*."},{"cle":{"type":"texte","acceptes":["hiciera"]},"affichage":"hiciera","explication":"**hiciera** : *hicieron* − *-ron* = *hicie-*, plus *-ra*. Un verbe irrégulier suit la même règle."},{"cle":{"type":"trous","trous":[["pusiera"]]},"affichage":"pusiera","explication":"**pusiera** : *quería que* (passé) + imparfait du subjonctif, formé sur *pusieron*."}]$ex$::jsonb),
  ('0cccb5bd-e926-5645-98be-20330f76818b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le courriel de Clara : souhaits et hypothèses","competence":"comprendre-langue","situation":"Clara écrit à son amie Paula, partie étudier à l’étranger. Elle raconte sa semaine, et son courriel est riche en imparfait du subjonctif.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Clara","blocs":["Querida Paula:","Ayer mi madre me pidió que pusiera la mesa, y mi hermano quería que cenáramos pronto. Él habla siempre como si fuera el jefe de la casa.","¡Ojalá estuvieras aquí! Te echo de menos. Un abrazo, Clara"],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre verbes** à l’imparfait du subjonctif.","aide":"Ils se terminent tous par *-ra* ou *-ras* ou *-ramos* ; ne touche pas *pidió* ni *quería*.","type":"zone","document":"correo","multiple":true},{"enonce":"Associe chaque infinitif à son imparfait du subjonctif (yo).","aide":"Passe par le passé simple : *pusieron, fueron, estuvieron, tuvieron*.","type":"association","gauche":[{"id":"g0","texte":"poner"},{"id":"g1","texte":"ser o ir"},{"id":"g2","texte":"estar"},{"id":"g3","texte":"tener"}],"droite":[{"id":"d0","texte":"estuviera"},{"id":"d1","texte":"tuviera"},{"id":"d2","texte":"fuera"},{"id":"d3","texte":"pusiera"}]},{"enonce":"Complète la phrase avec les deux verbes qui conviennent.","aide":"Passés simples : *hicieron* et *leyeron*. Le verbe principal est au passé.","type":"trous","segments":["Mi padre me pidió que ",0," los deberes y que ",1," un libro."],"banque":["leyera","hiciera","hago","leo"]},{"enonce":"Choisis la forme correcte : « Si ___ más tiempo, aprendería chino. »","aide":"Après *si* d’hypothèse irréelle, on n’emploie jamais le conditionnel.","type":"choix","options":[{"id":"a","texte":"tengo"},{"id":"b","texte":"tuve"},{"id":"c","texte":"tendría"},{"id":"d","texte":"tuviera"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m16","m23","m30"]},"explication":"**pusiera, cenáramos, fuera, estuvieras** : quatre formes en *-ra*. Après *como si*, ou dans un souhait irréel (*ojalá*), on emploie toujours l’imparfait du subjonctif."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"*Poner* → **pusiera** ; *ser* et *ir* → **fuera** ; *estar* → **estuviera** ; *tener* → **tuviera**."},{"cle":{"type":"trous","trous":[["hiciera"],["leyera"]]},"affichage":"hiciera · leyera","explication":"**hiciera** (de *hicieron*) et **leyera** (de *leyeron*) : après *pidió que*, on met l’imparfait du subjonctif."},{"cle":{"type":"choix","ids":["d"]},"explication":"**tuviera** : l’hypothèse irréelle se construit avec *si* + imparfait du subjonctif, et le conditionnel dans la principale (*aprendería*)."}]$ex$::jsonb),
  ('0cccb5bd-e926-5645-98be-20330f76818b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Chasse aux fautes dans la conversation de Hugo et Lía","competence":"manier-langue","situation":"Hugo et Lía échangent des messages. Leur professeur leur demande de repérer et de corriger une faute, puis de classer les emplois de l’imparfait du subjonctif.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Mensajes de Hugo y Lía","participants":[{"nom":"Hugo","emoji":"👦","cote":"droite"},{"nom":"Lía","emoji":"👧","cote":"gauche"}],"repliques":[{"qui":"Hugo","texte":"Si tendría dinero, viajaría a Perú este verano."},{"qui":"Lía","texte":"¡Ojalá pudiera ir contigo! Mis padres querían que me quedara en casa."}],"source":"Messages écrits pour l’exercice"},{"id":"tabla","type":"tableau","titre":"La forma de nosotros","colonnes":["Infinitivo","Pretérito (ellos)","Nosotros (-ra)"],"lignes":[["hablar","hablaron","?"],["comer","comieron","comiéramos"],["tener","tuvieron","tuviéramos"],["poder","pudieron","pudiéramos"]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Hugo fait une **faute** dans son premier message. Touche le mot fautif.","aide":"Après *si* d’hypothèse irréelle, on n’emploie jamais le conditionnel.","type":"zone","document":"chat","multiple":false},{"enonce":"Écris la forme **correcte** de *tener* (yo) à la place de *tendría*.","aide":"Passé simple : *tuvieron* ; on retire *-ron*, on ajoute *-ra*.","type":"texte"},{"enonce":"Complète la case vide du tableau : *hablar*, forme **nosotros** en -ra (avec l’accent).","aide":"Retire *-ron* de *hablaron*, ajoute *-ramos* et accentue la syllabe avant *-ra-*.","type":"texte"},{"enonce":"Range chaque phrase selon l’emploi de l’imparfait du subjonctif.","aide":"Cherche le mot déclencheur : *quería que*, *si*, *como si*, ou une demande polie.","type":"categories","categories":[{"id":"c0","texte":"Concordance"},{"id":"c1","texte":"Hypothèse irréelle"},{"id":"c2","texte":"Como si"},{"id":"c3","texte":"Politesse"}],"items":[{"id":"i0","texte":"Mi madre pidió que pusiera la mesa"},{"id":"i1","texte":"Habla como si fuera el jefe"},{"id":"i2","texte":"Quería que vinieras"},{"id":"i3","texte":"Corre como si tuviera prisa"},{"id":"i4","texte":"Quisiera un café"},{"id":"i5","texte":"Si pudiera, iría contigo"},{"id":"i6","texte":"Quisiera pedir un favor"},{"id":"i7","texte":"Si fuera rico, compraría una isla"}]},{"enonce":"Complète la phrase d’hypothèse.","aide":"*Ser* et *ir* partagent la même base : *fueron*.","type":"trous","segments":["Si yo ",0," tú, iría con ellos."],"banque":["fui","fuera","soy","sería"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**tendría** est faux : après *si*, on met l’imparfait du subjonctif (*tuviera*) ; le conditionnel reste dans la principale (*viajaría*)."},{"cle":{"type":"texte","acceptes":["tuviera"]},"affichage":"tuviera","explication":"**tuviera** : *Si tuviera dinero, viajaría a Perú.*"},{"cle":{"type":"texte","acceptes":["hablaramos"]},"affichage":"habláramos","explication":"**habláramos** : la forme *nosotros* porte toujours un accent écrit (*habláramos, comiéramos, tuviéramos*)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c2","i4":"c3","i5":"c1","i6":"c3","i7":"c1"}},"explication":"*Quería que…* : **concordance** ; *si…, condicional* : **hypothèse irréelle** ; *como si…* : toujours l’imparfait du subjonctif ; *quisiera…* : **politesse**."},{"cle":{"type":"trous","trous":[["fuera"]]},"affichage":"fuera","explication":"**fuera** : *si yo fuera tú* est la formule de l’hypothèse irréelle (« si j’étais toi »)."}]$ex$::jsonb),
  ('f64e5ae0-9793-5095-a43a-6bfd8a4b2774'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Haber : l’auxiliaire unique","competence":"manier-langue","situation":"Pour réviser, Álvaro a rassemblé dans un tableau les temps composés construits avec *haber*. Il s’en sert pour compléter quelques phrases.","documents":[{"id":"tabla","type":"tableau","titre":"Los tiempos compuestos","colonnes":["Tiempo","Auxiliar haber","Ejemplo"],"lignes":[["Pretérito perfecto","he, has, ha…","he hablado"],["Pluscuamperfecto","había, habías, había…","había hablado"],["Futuro perfecto","habré, habrás, habrá…","habré hablado"],["Condicional perfecto","habría, habrías, habría…","habría hablado"]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Touche l’**exemple** du plus-que-parfait (*j’avais parlé*).","aide":"Le plus-que-parfait se construit avec *había*.","type":"zone","document":"tabla","multiple":false},{"enonce":"Complète la phrase avec l’auxiliaire qui convient.","aide":"Il faut une action antérieure à un moment du passé : *haber* à l’imparfait.","type":"trous","segments":["Cuando yo llegué, mis amigos ya se ",0," ido."],"banque":["habían","habrían","habrán","han"]},{"enonce":"Remets en ordre : « Je me suis levé tôt. » La phrase commence par *Me*.","aide":"Le pronom se place avant *haber*, qui n’est jamais séparé du participe.","type":"ordre","items":[{"id":"a","texte":"levantado temprano"},{"id":"b","texte":"he"},{"id":"c","texte":"Me"}]},{"enonce":"Associe chaque infinitif à son participe passé irrégulier.","aide":"Aucun de ces participes ne se termine par *-ado* ni *-ido*.","type":"association","gauche":[{"id":"g0","texte":"hacer"},{"id":"g1","texte":"abrir"},{"id":"g2","texte":"escribir"},{"id":"g3","texte":"ver"}],"droite":[{"id":"d0","texte":"escrito"},{"id":"d1","texte":"visto"},{"id":"d2","texte":"hecho"},{"id":"d3","texte":"abierto"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"**había hablado** : *haber* à l’imparfait + participe passé = plus-que-parfait."},{"cle":{"type":"trous","trous":[["habian"]]},"affichage":"habían","explication":"**habían** : le plus-que-parfait exprime une action déjà terminée avant un moment du passé (*cuando llegué*)."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"**Me he levantado temprano** : le pronom passe devant *haber*, et *haber* + participe forment un bloc."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"*Hacer* → **hecho** ; *abrir* → **abierto** ; *escribir* → **escrito** ; *ver* → **visto**."}]$ex$::jsonb),
  ('f64e5ae0-9793-5095-a43a-6bfd8a4b2774'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre à Pablo : quatre temps composés","competence":"comprendre-langue","situation":"Marina écrit à Pablo pour lui expliquer pourquoi elle n’a pas pu venir le voir. Sa lettre mêle plusieurs temps composés.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Marina","blocs":["Querido Pablo:","Esta mañana he preparado la maleta. Cuando llegué a la estación, el tren ya había salido; por eso no pude ir a verte.","En junio habré terminado el curso y podré viajar. Habría venido antes, pero estaba enferma."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** du plus-que-parfait.","aide":"C’est le temps de l’antériorité dans le passé : l’auxiliaire est à l’imparfait.","type":"zone","document":"carta","multiple":true},{"enonce":"Associe chaque temps de la lettre à son emploi.","aide":"Relis chaque phrase : dans laquelle l’action est-elle finie avant juin ? Laquelle n’a pas eu lieu ?","type":"association","gauche":[{"id":"g0","texte":"había salido"},{"id":"g1","texte":"habré terminado"},{"id":"g2","texte":"habría venido"}],"droite":[{"id":"d0","texte":"action achevée avant un moment futur"},{"id":"d1","texte":"irréel du passé"},{"id":"d2","texte":"antériorité dans le passé"}]},{"enonce":"Complète la phrase avec les deux participes passés irréguliers.","aide":"Les participes de *escribir* et de *abrir* sont irréguliers.","type":"trous","segments":["He ",0," la carta y he ",1," la ventana."],"banque":["escribido","escrito","abierto","abrido"]},{"enonce":"Dans « No veo a Ana: habrá llegado tarde », que exprime *habrá llegado* ?","aide":"La phrase commence par un constat au présent : *No veo a Ana*.","type":"choix","options":[{"id":"a","texte":"Une certitude : elle arrivera en retard demain"},{"id":"b","texte":"Un ordre : qu’elle arrive en retard"},{"id":"c","texte":"Une probabilité : elle a dû arriver en retard"},{"id":"d","texte":"Un souhait : si seulement elle était arrivée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m17"]},"explication":"**había salido** : *haber* à l’imparfait + participe. Le train était déjà parti quand Marina est arrivée."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"*Había salido* : **antériorité dans le passé** ; *habré terminado* : **achevé avant un moment futur** ; *habría venido* : **irréel du passé** (elle n’est pas venue)."},{"cle":{"type":"trous","trous":[["escrito"],["abierto"]]},"affichage":"escrito · abierto","explication":"**escrito** et **abierto** : après *haber*, le participe est invariable ; ces deux verbes ont un participe irrégulier."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Une probabilité** : le futur antérieur sert aussi à faire une supposition sur le passé proche (« elle a dû arriver en retard »)."}]$ex$::jsonb),
