   $ex${"titre":"Faux pas de conjugaison et traduction à compléter","competence":"manier-langue","situation":"Ana et Beto s’écrivent, mais leurs messages contiennent des fautes sur les temps composés. Leur professeur leur demande de les corriger puis de traduire une phrase.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Mensajes de Ana y Beto","participants":[{"nom":"Ana","emoji":"👩","cote":"gauche"},{"nom":"Beto","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Hoy me soy levantado muy tarde y he perdido el autobús."},{"qui":"Beto","texte":"Yo he abierto la ventana y he rompido un vaso."},{"qui":"Ana","texte":"¡Qué mala suerte! Las cartas que he escritas no llegaron."}],"source":"Messages écrits pour l’exercice"},{"id":"frase","type":"texte","genre":"consigne","titre":"Traduce","blocs":["« Quand nous sommes arrivés, Marta était déjà rentrée ; elle aurait dîné avec nous si nous l’avions prévenue. »"],"source":"Consigne écrite pour l’exercice"}],"questions":[{"enonce":"Ana emploie un **mauvais auxiliaire**. Touche-le.","aide":"Aux temps composés, l’auxiliaire est *haber*, jamais *ser*.","type":"zone","document":"chat","multiple":false},{"enonce":"Beto se trompe de participe. Écris le participe passé **correct** de *romper*.","aide":"Ce participe est irrégulier et très court.","type":"texte"},{"enonce":"Pourquoi *las cartas que he escritas* est-il faux ?","aide":"Pense à la règle d’or : un seul auxiliaire, et un participe qui ne bouge pas.","type":"choix","options":[{"id":"a","texte":"Parce que *cartas* est un nom du genre masculin"},{"id":"b","texte":"Parce que *haber* doit toujours être au pluriel"},{"id":"c","texte":"Parce que le verbe doit obligatoirement être au futur"},{"id":"d","texte":"Parce que le participe est invariable avec haber"}],"multiple":false},{"enonce":"Complète la traduction de la phrase de la consigne.","aide":"Une action antérieure, un irréel du passé, puis la condition (*si* + plus-que-parfait du subjonctif).","type":"trous","segments":["Cuando llegamos, Marta ya ",0," vuelto; ",1," cenado con nosotros si le ",2," avisado."],"banque":["había","habría","habrá","hemos","hubiéramos"]},{"enonce":"Associe chaque forme de *haber* au temps qu’elle construit.","aide":"*Haya* introduit un subjonctif ; *hube* appartient à la langue littéraire.","type":"association","gauche":[{"id":"g0","texte":"habré hablado"},{"id":"g1","texte":"habría hablado"},{"id":"g2","texte":"haya hablado"},{"id":"g3","texte":"hube hablado"}],"droite":[{"id":"d0","texte":"passé antérieur (littéraire)"},{"id":"d1","texte":"subjonctif passé"},{"id":"d2","texte":"conditionnel passé"},{"id":"d3","texte":"futur antérieur"}]}]}$ex$::jsonb,
