  ('5feda5f3-38a1-5656-a048-4d55476b08ca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le parcours de Marta","competence":"comprendre-langue","situation":"Dans un blog, un journaliste raconte les changements de la vie de Marta. Chaque changement a son verbe.","documents":[{"id":"blog","type":"texte","genre":"recit","titre":"La vida de Marta","blocs":["De niña, Marta se ponía roja cuando hablaba en público. Con los años, se hizo abogada y, después de muchos esfuerzos, llegó a ser jueza.","Hace un año, perdió su trabajo y se quedó sin empleo. Desde entonces, se ha vuelto muy desconfiada."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui marque l’**état résultant d’un événement** (la perte du travail).","aide":"Le verbe est suivi de *sin empleo*.","type":"zone","document":"blog","multiple":false},{"enonce":"Pourquoi le texte dit-il *llegó a ser jueza* plutôt que *se hizo jueza* ?","aide":"Regarde l’expression qui précède : « después de muchos esfuerzos ».","type":"choix","options":[{"id":"a","texte":"Parce que *jueza* est un adjectif qualificatif"},{"id":"b","texte":"Parce que c’est un changement tout à fait passager"},{"id":"c","texte":"Parce que c’est l’aboutissement d’un long parcours"},{"id":"d","texte":"Parce que Marta n’a jamais voulu ce métier"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"La cécité est le résultat d’un événement brutal.","type":"trous","segments":["Mi abuelo se ",0," ciego después de un accidente."],"banque":["puso","convirtió","hizo","quedó"]},{"enonce":"Associe chaque verbe qui contient déjà l’idée de changement à sa traduction.","aide":"Chacun de ces verbes dérive d’un adjectif : *viejo*, *rico*, *delgado*, *loco*.","type":"association","gauche":[{"id":"g0","texte":"envejecer"},{"id":"g1","texte":"enriquecerse"},{"id":"g2","texte":"adelgazar"},{"id":"g3","texte":"enloquecer"}],"droite":[{"id":"d0","texte":"devenir fou"},{"id":"d1","texte":"maigrir"},{"id":"d2","texte":"vieillir"},{"id":"d3","texte":"s’enrichir"}]}]}$ex$::jsonb,
