  ('5feda5f3-38a1-5656-a048-4d55476b08ca'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qu’est devenu Marcos ? Un échange et ses nuances","competence":"comprendre-langue","situation":"Lucía retrouve Tomás et lui demande des nouvelles d’un ancien camarade. Leur échange mêle plusieurs verbes de changement dont il faut saisir les nuances.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Mensajes de Lucía y Tomás","participants":[{"nom":"Lucía","emoji":"👩","cote":"gauche"},{"nom":"Tomás","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Lucía","texte":"¿Qué ha sido de Marcos? No lo veo desde el instituto."},{"qui":"Tomás","texte":"Estudió medicina y se hizo cirujano. Y su hermano tuvo un accidente y se quedó sin trabajo."},{"qui":"Tomás","texte":"Al principio se puso muy triste, pero hoy está mejor."}],"source":"Messages écrits pour l’exercice"},{"id":"tabla","type":"tableau","titre":"Matices","colonnes":["Frase","Sentido"],"lignes":[["Se puso triste","triste en ese momento"],["Se volvió triste","se ha convertido en alguien triste"],["Se hizo famoso","famoso gracias a su trabajo"],["Llegó a ser famoso","famoso al final de un largo camino"]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Touche la **formule** qui demande ce qu’est devenu Marcos.","aide":"Elle commence par *Qué* et se termine par *de*.","type":"zone","document":"chat","multiple":true},{"enonce":"Touche la phrase qui marque l’**aboutissement d’un long parcours**, avec une idée de mérite.","aide":"Elle utilise *llegar a ser*.","type":"zone","document":"tabla","multiple":false},{"enonce":"Pourquoi Tomás dit-il *se puso muy triste* et non *se volvió triste* ?","aide":"Observe la fin du message : « hoy está mejor ».","type":"choix","options":[{"id":"a","texte":"Parce que le frère l’a voulu ainsi"},{"id":"b","texte":"Parce que *ponerse* exprime un métier"},{"id":"c","texte":"Parce que la tristesse était passagère"},{"id":"d","texte":"Parce que la tristesse est devenue son caractère"}],"multiple":false},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"*Acabar* + gérondif signifie « finir par ».","type":"association","gauche":[{"id":"g0","texte":"Il s’est retrouvé sans travail"},{"id":"g1","texte":"Il a fini par devenir mon meilleur ami"},{"id":"g2","texte":"Il est devenu chef de section"},{"id":"g3","texte":"Qu’est devenu ton frère ?"}],"droite":[{"id":"d0","texte":"¿Qué ha sido de tu hermano?"},{"id":"d1","texte":"Se quedó sin trabajo"},{"id":"d2","texte":"Acabó siendo mi mejor amigo"},{"id":"d3","texte":"Pasó a ser jefe de sección"}]},{"enonce":"Range chaque phrase selon le type de changement.","aide":"Pense au verbe : *ponerse* passe, *volverse* change en profondeur, *quedarse* résulte d’un événement.","type":"categories","categories":[{"id":"c0","texte":"Cambio pasajero"},{"id":"c1","texte":"Cambio profundo"},{"id":"c2","texte":"Resultado de un hecho"}],"items":[{"id":"i0","texte":"Se quedó viudo"},{"id":"i1","texte":"Me pongo nervioso antes del examen"},{"id":"i2","texte":"Se puso rojo al hablar"},{"id":"i3","texte":"Se volvió loco"},{"id":"i4","texte":"Se quedó ciego"},{"id":"i5","texte":"Se ha vuelto desconfiado"}]}]}$ex$::jsonb,
