  ('250ebfc4-ec73-5642-9c1a-735816db2665'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les petites annonces du quartier","competence":"manier-langue","situation":"Dans la rue, Olivia lit les annonces affichées sur le panneau du quartier. Elle remarque comment l’espagnol dit « on » sans pronom.","documents":[{"id":"avisos","type":"fiche","modele":"panneau","entete":"AVISOS DEL BARRIO","sousTitre":"Madrid","emoji":"📌","lignes":[{"texte":"Se habla español","id":"z1"},{"texte":"Se alquilan habitaciones","id":"z2"},{"texte":"Se vende piso","id":"z3"},{"texte":"Se prohíbe fumar","id":"z4"}],"pied":"Ayuntamiento del barrio","teinte":"bleu","source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’annonce dont le verbe est au **pluriel**.","aide":"Le verbe s’accorde avec le complément de chose : cherche un nom pluriel.","type":"zone","document":"avisos","multiple":false},{"enonce":"Touche l’annonce qui veut dire « **On parle espagnol** ».","aide":"Pense au verbe *hablar*.","type":"zone","document":"avisos","multiple":false},{"enonce":"Complète l’annonce.","aide":"*Pisos* est au pluriel.","type":"trous","segments":["Se ",0," pisos antiguos."],"banque":["venden","vende","vendemos","vendo"]},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"Sens général : *se*. Les autres, sans moi : 3e personne du pluriel. Un groupe qui m’inclut : *nosotros*.","type":"association","gauche":[{"id":"g0","texte":"Ici, on vit bien"},{"id":"g1","texte":"On vend des appartements"},{"id":"g2","texte":"On frappe à la porte"},{"id":"g3","texte":"Chez nous, on déjeune à deux heures"}],"droite":[{"id":"d0","texte":"Aquí se vive bien"},{"id":"d1","texte":"Llaman a la puerta"},{"id":"d2","texte":"Se venden pisos"},{"id":"d3","texte":"En casa comemos a las dos"}]}]}$ex$::jsonb,
