  ('250ebfc4-ec73-5642-9c1a-735816db2665'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une bibliothèque inaugurée : actif, passif et résultat","competence":"comprendre-langue","situation":"Dans le journal du quartier, un article annonce l’ouverture d’une bibliothèque. Marta s’en sert pour comparer les différentes façons de dire « on » ou de former le passif.","documents":[{"id":"prensa","type":"texte","genre":"article","titre":"Nueva biblioteca","blocs":["La biblioteca del barrio fue inaugurada por la alcaldesa el lunes. Los libros fueron donados por los vecinos.","Se aceptan nuevos socios. En casa ya hablamos de ir todos los sábados."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** de la voix passive qui disent que la bibliothèque a été **inaugurée** par la maire.","aide":"La voix passive est formée de *ser* + participe accordé, suivie de *por* + l’agent.","type":"zone","document":"prensa","multiple":true},{"enonce":"Complète la phrase à la voix passive.","aide":"Il faut *ser* au pluriel et au passé simple.","type":"trous","segments":["Los premios ",0," entregados por el director del museo."],"banque":["fue","sido","estar","fueron"]},{"enonce":"Quelle phrase exprime le **résultat** (la porte est ouverte parce que quelqu’un l’a ouverte) ?","aide":"Pour un état, un résultat, on emploie *estar* + participe.","type":"choix","options":[{"id":"a","texte":"La puerta es abierta."},{"id":"b","texte":"La puerta está abierta."},{"id":"c","texte":"La puerta ha abierta."},{"id":"d","texte":"La puerta se abierta."}],"multiple":false},{"enonce":"Associe chaque tournure de « on » à son emploi.","aide":"Pense à qui est inclus dans le « on » : tout le monde, les autres, nous.","type":"association","gauche":[{"id":"g0","texte":"Aquí se vive bien"},{"id":"g1","texte":"Llaman a la puerta"},{"id":"g2","texte":"En casa comemos a las dos"},{"id":"g3","texte":"Uno se acostumbra a todo"}],"droite":[{"id":"d0","texte":"sens général, impersonnel"},{"id":"d1","texte":"un groupe qui m’inclut"},{"id":"d2","texte":"verbe déjà pronominal"},{"id":"d3","texte":"les autres, sans moi"}]}]}$ex$::jsonb,
