  ('250ebfc4-ec73-5642-9c1a-735816db2665'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les erreurs du « se » passif dans une conversation","competence":"manier-langue","situation":"Ana et Beto échangent des messages au sujet d’une annonce et d’une nouvelle du journal. Leur professeur leur demande de corriger les accords du « se » passif.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Mensajes de Ana y Beto","participants":[{"nom":"Ana","emoji":"👩","cote":"gauche"},{"nom":"Beto","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Mira el anuncio: se vende pisos antiguos en el centro."},{"qui":"Beto","texte":"Y en las noticias dicen que se detuvieron a los ladrones del banco."}],"source":"Messages écrits pour l’exercice"},{"id":"tabla","type":"tableau","titre":"El «se» pasivo","colonnes":["Complemento","Verbo","Ejemplo"],"lignes":[["una cosa en plural","plural","Se venden pisos."],["una persona precisa con *a*","singular","Se detuvo a los ladrones."]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Ana fait une **faute d’accord**. Touche le verbe fautif.","aide":"Le complément *pisos* est une chose au pluriel.","type":"zone","document":"chat","multiple":false},{"enonce":"Écris la forme **correcte** du verbe *vender* dans l’annonce d’Ana.","aide":"Le verbe doit s’accorder avec *pisos*.","type":"texte"},{"enonce":"Touche la case qui donne le **nombre du verbe** quand le complément est une personne précise introduite par *a*.","aide":"Lis la deuxième ligne du tableau.","type":"zone","document":"tabla","multiple":false},{"enonce":"Corrige le message de Beto en complétant la phrase.","aide":"Les voleurs sont des personnes précises, introduites par *a*.","type":"trous","segments":["En las noticias dicen que se ",0," a los ladrones del banco."],"banque":["detenidos","detuvieron","detuvo","detener"]},{"enonce":"Range chaque phrase selon la façon dont elle traduit « on ».","aide":"Repère le verbe : un *se*, un pluriel sans sujet, une 1re personne du pluriel, ou le pronom *uno*.","type":"categories","categories":[{"id":"c0","texte":"se + 3e personne"},{"id":"c1","texte":"3e personne du pluriel"},{"id":"c2","texte":"nosotros"},{"id":"c3","texte":"uno"}],"items":[{"id":"i0","texte":"Dicen que va a llover"},{"id":"i1","texte":"Llaman a la puerta"},{"id":"i2","texte":"Aquí se vive bien"},{"id":"i3","texte":"En casa comemos a las dos"},{"id":"i4","texte":"Uno se acostumbra a todo"},{"id":"i5","texte":"Se venden pisos"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**vende** est faux : un complément de chose au pluriel exige un verbe au pluriel, donc *se venden pisos*."},{"cle":{"type":"texte","acceptes":["venden"]},"affichage":"venden","explication":"**venden** : *se venden pisos antiguos*, accord au pluriel avec le complément de chose."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**Singulier** : avec une personne précise introduite par *a*, le verbe reste au singulier (*se detuvo a los ladrones*)."},{"cle":{"type":"trous","trous":[["detuvo"]]},"affichage":"detuvo","explication":"**detuvo** : le complément est une personne introduite par *a*, donc le verbe reste au singulier."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c2","i4":"c3","i5":"c0"}},"explication":"*Se vive, se venden* : **se + verbe** ; *dicen, llaman* : **3e personne du pluriel** ; *comemos* : **nosotros** ; *uno se acostumbra* : **uno**."}]$ex$::jsonb),
  ('8cfabdb6-e922-5101-845e-8586908a536e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Indicatif ou subjonctif après cuando ?","competence":"manier-langue","situation":"Pour son contrôle, Iván a résumé la règle des subordonnées de temps dans un tableau. Il s’en sert pour répondre à quelques questions.","documents":[{"id":"tabla","type":"tableau","titre":"Cuando + verbo","colonnes":["Acción","Modo","Ejemplo"],"lignes":[["habitual o pasada","indicativo","Cuando llego, cenamos."],["por venir","subjuntivo","Cuando llegues, cenaremos."]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Touche le **mode** qu’on emploie pour une action à venir.","aide":"Regarde la ligne « por venir ».","type":"zone","document":"tabla","multiple":false},{"enonce":"Complète la phrase (action à venir).","aide":"Après *cuando* + action à venir, on emploie le subjonctif présent.","type":"trous","segments":["Cuando ",0," tiempo, llámame."],"banque":["tienes","tengas","tendrás","tuviste"]},{"enonce":"Associe chaque conjonction de temps à sa traduction.","aide":"*Hasta* indique une limite dans le temps.","type":"association","gauche":[{"id":"g0","texte":"cuando"},{"id":"g1","texte":"en cuanto"},{"id":"g2","texte":"hasta que"},{"id":"g3","texte":"cada vez que"}],"droite":[{"id":"d0","texte":"dès que"},{"id":"d1","texte":"quand"},{"id":"d2","texte":"jusqu’à ce que"},{"id":"d3","texte":"chaque fois que"}]},{"enonce":"Quelle phrase est correcte ?","aide":"Jamais de futur après *cuando*.","type":"choix","options":[{"id":"a","texte":"Cuando llegarás, llámame."},{"id":"b","texte":"Cuando llegues, llámame."},{"id":"c","texte":"Cuando llegas, llámame mañana."},{"id":"d","texte":"Cuando llegáramos, llámame."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**subjuntivo** : après *cuando*, une action pas encore réalisée se met au subjonctif présent."},{"cle":{"type":"trous","trous":[["tengas"]]},"affichage":"tengas","explication":"**tengas** : en français on dit « quand tu auras », mais l’espagnol met le subjonctif présent."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"*Cuando* = **quand** ; *en cuanto* = **dès que** ; *hasta que* = **jusqu’à ce que** ; *cada vez que* = **chaque fois que**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Cuando llegues, llámame.** : le futur français devient un subjonctif présent en espagnol."}]$ex$::jsonb),
  ('8cfabdb6-e922-5101-845e-8586908a536e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les projets d’Inés pour l’été","competence":"comprendre-langue","situation":"Inés écrit à Hugo pour lui parler de ses projets après le lycée. Sa lettre alterne les temps selon que les actions sont habituelles ou à venir.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Inés","blocs":["Querido Hugo:","Cuando termine el instituto, viajaré a Perú. En cuanto llegue, te llamaré, y me quedaré allí hasta que no me quede dinero.","Mientras tanto, cada día, cuando vuelvo a casa, estudio español."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes** au subjonctif présent (actions à venir).","aide":"Ils suivent *cuando*, *en cuanto* et *hasta que* et parlent de ce qui n’a pas encore eu lieu.","type":"zone","document":"carta","multiple":true},{"enonce":"Pourquoi Inés écrit-elle *cuando vuelvo* à l’indicatif ?","aide":"Regarde l’expression « cada día ».","type":"choix","options":[{"id":"a","texte":"Parce que l’action est encore à venir"},{"id":"b","texte":"Parce que c’est une action habituelle"},{"id":"c","texte":"Parce qu’elle parle du passé lointain"},{"id":"d","texte":"Parce que le sujet est le même"}],"multiple":false},{"enonce":"Complète la tournure avec l’infinitif.","aide":"La tournure signifie « en sortant ».","type":"trous","segments":[0," salir del cine, vimos a Luis."],"banque":["Al","Mientras","En","Cuando"]},{"enonce":"Associe chaque tournure avec l’infinitif à sa traduction.","aide":"*Nada más llegar* : dès l’arrivée.","type":"association","gauche":[{"id":"g0","texte":"al + infinitif"},{"id":"g1","texte":"nada más + infinitif"},{"id":"g2","texte":"antes de + infinitif"},{"id":"g3","texte":"después de + infinitif"}],"droite":[{"id":"d0","texte":"avant de"},{"id":"d1","texte":"au moment où, en"},{"id":"d2","texte":"après avoir"},{"id":"d3","texte":"dès que, à peine"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m11","m22"]},"explication":"**termine, llegue, quede** : après une conjonction de temps, une action à venir se met au subjonctif."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Action habituelle** : *cuando vuelvo a casa* décrit ce qu’elle fait chaque jour, donc l’indicatif."},{"cle":{"type":"trous","trous":[["al"]]},"affichage":"Al","explication":"**Al salir** : *al* + infinitif exprime « au moment où » (même sujet dans les deux propositions)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"*Al salir* = **en sortant** ; *nada más llegar* = **dès son arrivée** ; *antes de comer* = **avant de manger** ; *después de comer* = **après avoir mangé**."}]$ex$::jsonb),
  ('8cfabdb6-e922-5101-845e-8586908a536e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une visite à organiser : quand, jusqu’à quand, avant quoi ?","competence":"manier-langue","situation":"Marta et Leo organisent la visite de Leo. Leurs messages alternent les conjonctions de temps ; il faut choisir le bon mode et le bon temps, y compris au passé.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Mensajes de Marta y Leo","participants":[{"nom":"Marta","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"¿Cuándo vienes a verme?"},{"qui":"Leo","texte":"En cuanto termine mis exámenes. Y me quedaré hasta que empiece el curso."},{"qui":"Marta","texte":"Perfecto. Llámame cuando llegues a la estación."}],"source":"Messages écrits pour l’exercice"},{"id":"tabla","type":"tableau","titre":"Conjunciones de tiempo","colonnes":["Conjunción","Sentido"],"lignes":[["cuando","quand"],["en cuanto","dès que"],["hasta que","jusqu’à ce que"],["antes de que","avant que"],["cada vez que","chaque fois que"]],"enteteLignes":true,"source":"Tableau réalisé pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes** au subjonctif présent.","aide":"Ils suivent *en cuanto*, *hasta que* et *cuando* et expriment une action à venir.","type":"zone","document":"chat","multiple":true},{"enonce":"Leo dit qu’il restera « jusqu’à ce que le cours commence ». Touche la **conjonction** qu’il emploie.","aide":"Cherche la ligne dont le sens est « jusqu’à ce que ».","type":"zone","document":"tabla","multiple":false},{"enonce":"Mets la phrase au passé (concordance).","aide":"Vu depuis le passé, le subjonctif présent devient un imparfait du subjonctif.","type":"trous","segments":["Leo dijo que se quedaría hasta que ",0," el curso."],"banque":["empiece","empezará","empezó","empezara"]},{"enonce":"Complète avec la conjonction toujours suivie du subjonctif.","aide":"Elle signifie « avant que ».","type":"trous","segments":["Llámame ",0," que se acabe la película."],"banque":["cada vez","mientras","cuando","antes de"]},{"enonce":"Range chaque phrase selon le mode utilisé après la conjonction.","aide":"Indicatif : action habituelle ou passée. Subjonctif : action pas encore réalisée.","type":"categories","categories":[{"id":"c0","texte":"Indicatif"},{"id":"c1","texte":"Subjonctif"}],"items":[{"id":"i0","texte":"Cuando llego, ceno"},{"id":"i1","texte":"Espera hasta que vuelva"},{"id":"i2","texte":"Cuando llegues, cenaremos"},{"id":"i3","texte":"Mientras cocino, escucho música"},{"id":"i4","texte":"En cuanto termine, te llamo"},{"id":"i5","texte":"Cuando llegué, cené"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m14","m20"]},"explication":"**termine, empiece, llegues** : trois subjonctifs présents, pour des actions pas encore réalisées."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**hasta que** : « jusqu’à ce que », suivi du subjonctif quand l’action est à venir."},{"cle":{"type":"trous","trous":[["empezara"]]},"affichage":"empezara","explication":"**empezara** : si l’action future est vue depuis le passé, le subjonctif passe à l’imparfait."},{"cle":{"type":"trous","trous":[["antes de"]]},"affichage":"antes de","explication":"**antes de que** : cette conjonction est toujours suivie du subjonctif, même si l’action est habituelle."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"*Llego, llegué, cocino* : **indicatif** (habituel, passé ou en cours) ; *llegues, termine, vuelva* : **subjonctif** (action à venir)."}]$ex$::jsonb),
  ('176fa557-6b35-5ac1-8843-4dcf4ee2299c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le courriel de Nora à Eva","competence":"comprendre-langue","situation":"Nora explique à Eva pourquoi elle n’est pas sortie le week-end et comment elle a réussi son examen.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Nora","blocs":["Querida Eva:","Como llovía mucho, no salí el sábado. Estaba tan cansada que me acosté a las ocho. Aprobé el examen gracias a tu ayuda."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **connecteur de cause** placé en tête de phrase.","aide":"En tête de phrase, on n’emploie pas *porque*.","type":"zone","document":"correo","multiple":false},{"enonce":"Touche l’**expression** qui exprime une cause heureuse.","aide":"Elle se traduit par « grâce à ».","type":"zone","document":"correo","multiple":true},{"enonce":"Complète la phrase d’intensité.","aide":"*Ruido* est un nom masculin singulier.","type":"trous","segments":["Había ",0," ruido que no pude estudiar."],"banque":["mucho","tan","tanto","tanta"]},{"enonce":"Quelle phrase est correcte ?","aide":"*Porque* ne se place jamais en tête de phrase pour exprimer la cause.","type":"choix","options":[{"id":"a","texte":"Llovía como no salí."},{"id":"b","texte":"Como llovía, no salí."},{"id":"c","texte":"Porque llovía, no salí."},{"id":"d","texte":"Como llovía porque no salí."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"**Como** : il se place en tête de phrase : *Como llovía, no salí*."},{"cle":{"type":"zone","ids":["m21","m22"]},"explication":"**gracias a** : cause heureuse (*aprobé gracias a tu ayuda*)."},{"cle":{"type":"trous","trous":[["tanto"]]},"affichage":"tanto","explication":"**tanto ruido que** : *tanto* + nom + *que* exprime la conséquence liée à l’intensité."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Como llovía, no salí.** : on commence par *como*, ou on écrit *No salí porque llovía*."}]$ex$::jsonb),
  ('176fa557-6b35-5ac1-8843-4dcf4ee2299c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pourquoi Dani n’est pas venu à la fête","competence":"comprendre-langue","situation":"Noa demande à Dani pourquoi il n’est pas venu à la fête. Leur échange contient plusieurs connecteurs de cause et de conséquence.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Mensajes de Noa y Dani","participants":[{"nom":"Noa","emoji":"👧","cote":"gauche"},{"nom":"Dani","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Noa","texte":"¿Por qué no viniste a la fiesta?"},{"qui":"Dani","texte":"Como estaba enfermo, me quedé en casa. Estaba tan cansado que me dormí a las nueve."},{"qui":"Noa","texte":"Ya que estás mejor, ven mañana."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce la **conséquence liée à l’intensité** (« si fatigué que… »).","aide":"Il précède l’adjectif *cansado*.","type":"zone","document":"chat","multiple":false},{"enonce":"Complète la phrase avec le connecteur de cause soutenu.","aide":"Il faut un connecteur de cause du registre soutenu suivi d’un nom.","type":"trous","segments":["Se suspendió el partido ",0," la lluvia."],"banque":["porque","gracias a","debido a","así que"]},{"enonce":"Touche l’**expression** qui introduit une cause connue de tous.","aide":"Elle se traduit par « puisque ».","type":"zone","document":"chat","multiple":true},{"enonce":"Associe chaque connecteur à sa nuance.","aide":"Pense à la place du connecteur dans la phrase.","type":"association","gauche":[{"id":"g0","texte":"porque"},{"id":"g1","texte":"como"},{"id":"g2","texte":"gracias a"},{"id":"g3","texte":"conque"}],"droite":[{"id":"d0","texte":"se place après la principale"},{"id":"d1","texte":"registre familier"},{"id":"d2","texte":"se place en tête de phrase"},{"id":"d3","texte":"cause heureuse"}]},{"enonce":"Quelle phrase exprime un **but** (« pour que tous t’entendent ») ?","aide":"*De modo que* + subjonctif exprime le but, *de modo que* + indicatif exprime la conséquence.","type":"choix","options":[{"id":"a","texte":"Habló alto de modo que todos lo oyeron."},{"id":"b","texte":"Habló tan alto que todos lo oyeron."},{"id":"c","texte":"Habla alto de modo que todos te oigan."},{"id":"d","texte":"Habló alto, así que todos lo oyeron."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**tan** : *tan* + adjectif + *que* exprime la conséquence (*tan cansado que me dormí*)."},{"cle":{"type":"trous","trous":[["debido a"]]},"affichage":"debido a","explication":"**debido a** : cause du registre soutenu, suivi d’un nom. *Gracias a* exprime une cause heureuse et *porque* est suivi d’un verbe."},{"cle":{"type":"zone","ids":["m23","m24"]},"explication":"**ya que** = puisque : elle présente une cause que tout le monde connaît."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"*Porque* : **après la principale** ; *como* : **en tête** ; *gracias a* : **cause heureuse** ; *conque* : **familier** (« alors »)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**de modo que todos te oigan** : *de modo que* + subjonctif exprime le but ; avec l’indicatif, il exprime la conséquence."}]$ex$::jsonb),
  ('176fa557-6b35-5ac1-8843-4dcf4ee2299c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les loyers montent, Lucas reste chez ses parents","competence":"argumenter","situation":"Dans une ville imaginaire, Lucas, étudiant de 20 ans, ne peut plus se payer un appartement. Pour un débat, on croise un graphique des loyers et son témoignage afin d’expliquer causes et conséquences.","documents":[{"id":"grafico","type":"graphique","forme":"barres","titre":"Alquiler medio de un piso pequeño","categories":["2019","2020","2021","2022","2023"],"series":[{"nom":"Alquiler (€/mes)","valeurs":[500,550,600,700,800],"teinte":"turquoise"}],"axeY":{"titre":"Alquiler medio","unite":"euros por mes","min":0,"max":800,"pas":100},"axeX":{"titre":"Año"},"valeurs":false,"source":"Chiffres imaginés pour l’exercice"},{"id":"testimonio","type":"texte","genre":"article","titre":"Testimonio de Lucas","blocs":["Me llamo Lucas, tengo veinte años y estudio en la ciudad. Sigo viviendo con mis padres porque el alquiler es muy caro. Cuando empecé la universidad, pagar un piso ya era difícil; ahora es imposible."],"source":"Témoignage écrit pour l’exercice"}],"questions":[{"enonce":"De combien d’**euros par mois** le loyer moyen a-t-il augmenté entre 2019 et 2023 ?","aide":"Lis la hauteur de la barre de 2019 et celle de 2023.","type":"nombre","unite":"€"},{"enonce":"Touche le **connecteur de cause** par lequel Lucas explique pourquoi il vit chez ses parents.","aide":"Il se place après la proposition principale.","type":"zone","document":"testimonio","multiple":false},{"enonce":"De quel **pourcentage** le loyer a-t-il augmenté entre 2019 et 2023 ?","aide":"Divise la hausse par le loyer de départ (2019), puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Complète la phrase de conséquence.","aide":"Après un verbe, on emploie *tanto que* ; puis il faut un connecteur de conséquence.","type":"trous","segments":["Los alquileres han subido ",0," que Lucas no puede pagar un piso; ",1,", sigue viviendo con sus padres."],"banque":["como","tan","por eso","tanto"]},{"enonce":"Complète la phrase où Lucas nie une cause.","aide":"*No porque* se construit avec le subjonctif.","type":"trous","segments":["No vivo con mis padres porque ",0," cómodo, sino porque no puedo pagar un piso."],"banque":["estar","estoy","estaré","esté"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 €","explication":"800 − 500 = **300 € par mois** de hausse entre 2019 et 2023."},{"cle":{"type":"zone","ids":["m16"]},"explication":"**porque** : il introduit la cause après la principale (*sigo viviendo con mis padres porque…*)."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 %","explication":"300 ÷ 500 = 0,6 donc **60 %** d’augmentation."},{"cle":{"type":"trous","trous":[["tanto"],["por eso"]]},"affichage":"tanto · por eso","explication":"**tanto** (*verbe + tanto que*) et **por eso** (« c’est pourquoi ») : les loyers ont tellement monté que Lucas reste chez ses parents."},{"cle":{"type":"trous","trous":[["este"]]},"affichage":"esté","explication":"**esté** : pour nier une cause, on emploie *no porque* + subjonctif, puis *sino porque* + indicatif pour donner la vraie cause."}]$ex$::jsonb),
