   $ex${"titre":"Tout est dit, rien n’est entendu","competence":"argumenter","situation":"Anaïs et Malik se disputent sur le prologue. Appuie-toi sur une scène écrite pour l’exercice, à la manière de Cocteau.","documents":[{"id":"db","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Anaïs","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anaïs","texte":"Le prologue annonce toute l’histoire : plus aucune émotion possible."},{"qui":"Malik","texte":"Au contraire : le décalage entre le ton familier et la fin fatale fait l’émotion."}]},{"id":"sc","type":"texte","genre":"theatre","titre":"Une scène à la manière de Cocteau","blocs":[{"personnage":"La Voix","replique":"Regarde, spectateur : une jeune reine se plaint de son écharpe, un jeune roi se réjouit de sa couronne. Tout est dit ; rien n’est entendu."},{"personnage":"Jocaste","replique":"Cette écharpe m’étrangle ! Je ne sais pas pourquoi je la garde."},{"personnage":"Œdipe","replique":"Je serai un roi que Thèbes n’oubliera jamais."}],"source":"Texte écrit pour l’exercice, à la manière de Cocteau"}],"questions":[{"enonce":"Dans le débat, touche le mot qui explique d’où vient l’émotion.","aide":"Malik répond à Anaïs en parlant d’un écart.","type":"zone","document":"db","multiple":false},{"enonce":"Dans la scène, touche l’objet qui annonce la mort de Jocaste.","aide":"Elle l’avoue : il l’étrangle.","type":"zone","document":"sc","multiple":false},{"enonce":"Range chaque élément : ce que Cocteau change ou ce qu’il garde du mythe.","aide":"Le ton et les inventions changent ; l’issue ne bouge pas.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’il change"},{"id":"c1","texte":"Ce qu’il garde"}],"items":[{"id":"i0","texte":"Œdipe qui s’aveugle"},{"id":"i1","texte":"Le suicide de Jocaste"},{"id":"i2","texte":"Un fantôme qui échoue à avertir"},{"id":"i3","texte":"Un Sphinx amoureux"},{"id":"i4","texte":"Le ton familier et insolent"}]},{"enonce":"Que prouve la scène dont le prologue dévoile tout ?","aide":"Le spectateur sait tout ; les personnages ne peuvent rien.","type":"choix","options":[{"id":"a","texte":"Le tragique est dans un mécanisme que rien n’enraye"},{"id":"b","texte":"Le tragique disparaît dès qu’on rit un peu"},{"id":"c","texte":"Le tragique naît toujours de la surprise finale"},{"id":"d","texte":"Le tragique exige un narrateur qui se cache"}],"multiple":false}]}$ex$::jsonb,
