   $ex${"titre":"« Vous » dans le compartiment","competence":"argumenter","situation":"Alice et Bastien débattent de ce roman où il ne se passe « rien ». Lis un court texte écrit pour l’exercice, à la manière de Butor, puis réponds.","documents":[{"id":"db","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Alice","emoji":"👧","cote":"gauche"},{"nom":"Bastien","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Alice","texte":"Ce roman est ennuyeux : il ne s’y passe rien."},{"qui":"Bastien","texte":"Il s’y passe un changement d’avis : c’est une pensée qui bascule."}]},{"id":"te","type":"texte","genre":"recit","titre":"Dans le compartiment","blocs":["Vous vous asseyez près de la fenêtre. Le paysage commence à défiler, et c’est Rome que vous voyez, non les champs. En face de vous, une femme tourne les pages d’un magazine : vous lui donnez un nom, une profession, un mari qui l’attend. Vous ne regardez plus l’heure. Vous cherchez la phrase que vous direz demain."],"source":"Texte écrit pour l’exercice, à la manière de Michel Butor"}],"questions":[{"enonce":"Dans le texte, touche le mot qui montre que le voyageur invente une vie à une inconnue.","aide":"Il lui donne ce qui permet de l’appeler.","type":"zone","document":"te","multiple":false},{"enonce":"Dans le débat, touche le mot qui dit où se joue l’action du roman.","aide":"Bastien répond à Alice.","type":"zone","document":"db","multiple":false},{"enonce":"Relie chaque procédé à son effet.","aide":"Pense au « vous », au mélange des temps, puis au lieu clos.","type":"association","gauche":[{"id":"g0","texte":"Un récit à la deuxième personne"},{"id":"g1","texte":"Trois temps mêlés"},{"id":"g2","texte":"Un seul compartiment, un seul trajet"}],"droite":[{"id":"d0","texte":"Le lecteur prend la place du personnage"},{"id":"d1","texte":"Un roman sans aventure : l’action est intérieure"},{"id":"d2","texte":"Le présent du trajet se charge de souvenirs et de rêves"}]},{"enonce":"Quelle conclusion de dissertation ce roman appuie-t-il le mieux ?","aide":"Il n’y a aucune péripétie extérieure.","type":"choix","options":[{"id":"a","texte":"Un roman exige un héros qui agit beaucoup"},{"id":"b","texte":"Un roman perd son intérêt quand il change de temps"},{"id":"c","texte":"Un roman peut être l’exploration d’une conscience"},{"id":"d","texte":"Un roman doit toujours raconter une aventure"}],"multiple":false}]}$ex$::jsonb,
