   $ex${"titre":"Vouloir, pouvoir, brûler","competence":"argumenter","situation":"Jade et Loïc discutent du fantastique de Balzac. L’inscription gravée sur la peau, citée dans le cours, t’aide à trancher.","documents":[{"id":"db","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Loïc","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jade","texte":"Un talisman, c’est du fantastique pur : le Paris du roman doit être inventé."},{"qui":"Loïc","texte":"Non : la peau est installée dans un Paris minutieusement décrit."}]},{"id":"in","type":"texte","genre":"source","titre":"L’inscription du talisman","blocs":["Si tu me possèdes, tu posséderas tout. Mais ta vie m’appartiendra."],"source":"Honoré de Balzac, *La Peau de chagrin* (1831), inscription du talisman"}],"questions":[{"enonce":"Dans l’inscription, touche les deux verbes qui promettent tout au possesseur.","aide":"Ils sont de la même famille.","type":"zone","document":"in","multiple":true},{"enonce":"Touche le mot qui dit ce que paie le possesseur.","aide":"Le prix n’est pas de l’argent.","type":"zone","document":"in","multiple":false},{"enonce":"Range chaque élément : détail réaliste ou élément fantastique.","aide":"Le Paris de 1830 est décrit avec précision ; seule la peau sort du réel.","type":"categories","categories":[{"id":"c0","texte":"Détail réaliste"},{"id":"c1","texte":"Élément fantastique"}],"items":[{"id":"i0","texte":"Une peau qui rétrécit à chaque souhait"},{"id":"i1","texte":"Une peau d’onagre qui exauce les vœux"},{"id":"i2","texte":"La ruine au jeu d’un jeune homme"},{"id":"i3","texte":"Un banquet chez le banquier Taillefer"},{"id":"i4","texte":"La spéculation de 1830"}]},{"enonce":"Que suggère, au-delà du conte, la peau qui s’use à chaque désir ?","aide":"Chaque désir est une dépense : qui paie, dans la société de 1830 ?","type":"choix","options":[{"id":"a","texte":"Une énergie qui se consume elle-même, comme l’époque"},{"id":"b","texte":"Un rêve d’enfant que l’adulte oublie très vite"},{"id":"c","texte":"Une punition pour les peintres de la bourgeoisie"},{"id":"d","texte":"Un simple jeu d’esprit sans rapport avec 1830"}],"multiple":false}]}$ex$::jsonb,
