  ('67a50787-9828-507d-9f6b-dc919507a8ed'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une seule fausse piste, tout un théâtre","competence":"argumenter","situation":"Deux élèves préparent l’oral sur le comique de situation dans *La Puce à l’oreille*. Complète leur plan avec ce que la pièce prouve.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Chez Feydeau, le rire vient des personnages : ils sont tous bêtes."},{"qui":"Lucas","texte":"Non : il vient de la machine. Un seul soupçon suffit à emballer les portes, les objets et les identités."},{"qui":"Nina","texte":"Alors les didascalies ne servent à rien ?"},{"qui":"Lucas","texte":"Au contraire : Feydeau les écrit avec minutie, le rythme est écrit."}]},{"id":"plan","type":"tableau","titre":"Le plan de l’oral","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le comique de situation est une mécanique","Un seul soupçon lance toute l’intrigue","Les bretelles de Raymonde"],["Le sosie fait vaciller l’identité","Chacun se prend pour un autre, jusqu’au vertige","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui, selon Lucas, suffit à lancer la pièce.","aide":"C’est ce que ressent Raymonde devant les bretelles.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Quel personnage est confondu avec un autre ?","type":"choix","options":[{"id":"a","texte":"Homenidès, mari jaloux qui reconnaît l’écriture de sa femme"},{"id":"b","texte":"Le docteur Finache, qui pose un palais d’argent à Camille"},{"id":"c","texte":"Poche, le sosie de Chandebise, que tout le monde prend pour lui"},{"id":"d","texte":"Lucienne, qui écrit la lettre anonyme à la place de Raymonde"}],"multiple":false},{"enonce":"Range chaque élément : relève-t-il de la mécanique des objets, ou du vertige des identités ?","aide":"Demande-toi : s’agit-il d’un dispositif de l’hôtel, ou de ce qui arrive à l’identité des gens ?","type":"categories","categories":[{"id":"c0","texte":"La machine des objets"},{"id":"c1","texte":"Le vertige des identités"}],"items":[{"id":"i0","texte":"Tout le monde se prend pour un autre"},{"id":"i1","texte":"Le lit tournant de l’hôtel"},{"id":"i2","texte":"Poche, sosie de Chandebise"},{"id":"i3","texte":"Les portes qui claquent"}]},{"enonce":"Quelle problématique cet échange permet-il le mieux de défendre ?","aide":"Reviens à la réplique de Lucas : où le rire prend-il sa source ?","type":"choix","options":[{"id":"a","texte":"Le rire de Feydeau naît d’une mécanique rigoureuse plus que de la psychologie"},{"id":"b","texte":"Les décors comptent plus que les paroles dans une pièce de Feydeau"},{"id":"c","texte":"Feydeau renonce à toute construction pour laisser jouer l’improvisation"},{"id":"d","texte":"Le théâtre de Feydeau est un drame psychologique sans aucun comique"}],"multiple":false}]}$ex$::jsonb,
