  ('505f783e-89c2-50f6-bfd0-b4ec0baf68de'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un poète en guerre, un livre en 1952","competence":"se-reperer-temps","situation":"Tu prépares l’oral sur *La Rage de l’expression*. Place le livre dans la vie de Francis Ponge, puis lis sa carte d’identité.","documents":[{"id":"fr","type":"frise","titre":"Ponge et ses livres","debut":1895,"fin":1990,"pas":5,"evenements":[{"id":"z1","date":1899,"nom":"Naissance"},{"id":"z2","date":1942,"nom":"Le Parti pris"},{"id":"z3","date":1952,"nom":"La Rage"},{"id":"z4","date":1988,"nom":"Mort"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"La Rage de l’expression","sousTitre":"Francis Ponge","emoji":"✍️","lignes":[{"texte":"Textes écrits","valeur":"Entre 1938 et 1944"},{"texte":"Livre publié","valeur":"En 1952"},{"texte":"Nature des textes","valeur":"Journaux d’écriture : datés, raturés, contradictoires"}],"pied":"Pas de vers, pas de rime","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche la date de publication de *La Rage de l’expression*.","aide":"Le livre paraît des années après l’écriture des textes.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent la fin de l’écriture des textes de la publication du livre ?","aide":"Prends la dernière année d’écriture et la date de publication de la fiche.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase avec la carte d’identité.","aide":"Relis la ligne « Nature des textes ».","type":"trous","segments":["Les textes sont des ",0," d’écriture : datés, raturés, ",1,"."],"banque":["journaux","recueils","définitifs","contradictoires"]}]}$ex$::jsonb,
