  ('505f783e-89c2-50f6-bfd0-b4ec0baf68de'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Une page de carnet, un dictionnaire ouvert","competence":"analyser-texte","situation":"Ponge n’achève pas ses textes : il montre son travail. Lis une page de carnet écrite pour l’exercice, à la manière de ses journaux d’écriture, puis regarde ce que contiennent trois de ses textes.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Une page de carnet","blocs":["Lundi. Première définition de la pomme de terre : tubercule. Non, je rature. J’ouvre le dictionnaire : l’étymologie me donne un mot, pas la chose.","Mardi. Deuxième définition. Rature encore. Aucune ne tient, je recommence.","Mercredi. Le mot manque : j’invente un mot. Une note brute, « sale, chaude, ronde », puis une phrase travaillée."],"source":"Texte écrit pour l’exercice, à la manière des journaux d’écriture de Ponge"},{"id":"textes","type":"tableau","titre":"Trois textes du recueil","colonnes":["Texte","Ce qu’on y voit"],"lignes":[["Le Carnet du bois de pins","Des pages de reprises sur un bois de pins, et des lettres sur ce travail même"],["La Mounine","?"],["Le Mimosa","Un objet aimé depuis l’enfance : l’affection gêne la description"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’outil que l’écrivain ouvre pour chercher l’origine des mots.","aide":"C’est un gros livre où l’on trouve les mots et leur histoire.","type":"zone","document":"carnet","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » pour « La Mounine » ?","aide":"Le titre « La Mounine » ne dit rien ; pense à l’échec du langage.","type":"choix","options":[{"id":"a","texte":"Un ciel de Provence vu en voyage, que le poète n’arrive pas à dire"},{"id":"b","texte":"Des lettres envoyées à un éditeur qui refuse le texte"},{"id":"c","texte":"Une guêpe observée sans pitié, décrite d’un seul jet"},{"id":"d","texte":"Un bois de pins décrit en vers réguliers et rimés"}],"multiple":false},{"enonce":"Relie chaque outil d’écriture à son usage.","aide":"La page de carnet montre déjà trois de ces gestes.","type":"association","gauche":[{"id":"g0","texte":"Le dictionnaire"},{"id":"g1","texte":"Les définitions successives"},{"id":"g2","texte":"Les néologismes"},{"id":"g3","texte":"La note brute et la phrase travaillée"}],"droite":[{"id":"d0","texte":"Ils servent quand la langue manque"},{"id":"d1","texte":"L’étymologie comme matière"},{"id":"d2","texte":"Aucune n’est la bonne"},{"id":"d3","texte":"Elles alternent dans le même texte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"Le **dictionnaire** (chez Ponge, le Littré) est ouvert en permanence : l’étymologie devient une matière."},{"cle":{"type":"choix","ids":["a"]},"explication":"Dans « La Mounine », Ponge **n’arrive pas à dire** un ciel de Provence vu en voyage."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"Chaque outil a son rôle : le **dictionnaire** donne l’étymologie, les **définitions** se succèdent sans qu’aucune soit la bonne, les **néologismes** comblent un manque, **notes brutes et phrases travaillées** alternent."}]$ex$::jsonb),
  ('505f783e-89c2-50f6-bfd0-b4ec0baf68de'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le galet n’est pas un miroir","competence":"argumenter","situation":"Deux élèves se disputent sur la façon dont Ponge décrit les choses. Lis leur échange, puis un court passage écrit à sa manière, et tranche.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Sami","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Quand Ponge décrit une guêpe, il parle de ses états d’âme : la guêpe, c’est lui."},{"qui":"Sami","texte":"Non : il refuse d’humaniser les choses. La chose n’est pas le miroir de ses sentiments."},{"qui":"Léa","texte":"Mais alors, que reste-t-il pour faire de la poésie ?"},{"qui":"Sami","texte":"L’exigence de justesse : nommer exactement."}]},{"id":"galet","type":"texte","genre":"recit","titre":"À la manière de Ponge","blocs":["Le galet. Je rature : « patient », je rature : « triste ». Je ne dois pas le prêter à moi-même. Il est poli par la mer, voilà tout, et il me faut le mot qui le dit."],"source":"Texte écrit pour l’exercice, à la manière de Ponge"}],"questions":[{"enonce":"Touche le verbe qui dit ce que Ponge refuse de faire avec les choses.","aide":"Sami explique que la chose n’est pas un miroir des sentiments.","type":"zone","document":"deb","multiple":false},{"enonce":"Dans le passage, touche le mot que l’auteur rature parce qu’il prête un sentiment au galet.","aide":"Cherche un mot qui désigne un état d’âme humain.","type":"zone","document":"galet","multiple":false},{"enonce":"Relie chaque procédé à son effet.","aide":"Pense à ce que chaque choix d’écriture change pour le lecteur.","type":"association","gauche":[{"id":"g0","texte":"Les reprises et les ratures"},{"id":"g1","texte":"Ni vers ni rime"},{"id":"g2","texte":"Le « je » d’un ouvrier au travail"},{"id":"g3","texte":"Le refus de l’humanisation"}],"droite":[{"id":"d0","texte":"Le poème devient un processus, non un résultat"},{"id":"d1","texte":"Le lecteur est placé dans l’atelier"},{"id":"d2","texte":"La chose est un défi posé au langage"},{"id":"d3","texte":"La poésie tient à l’exigence de justesse"}]},{"enonce":"Quelle conclusion de dissertation ce travail permet-il le mieux d’appuyer ?","aide":"Un poème fait de brouillons et de ratures montre quoi ?","type":"choix","options":[{"id":"a","texte":"Le poème doit exprimer d’abord les émotions personnelles du poète"},{"id":"b","texte":"Le poème peut être le compte rendu de sa propre fabrication"},{"id":"c","texte":"Le poème perd tout intérêt dès qu’il est écrit en prose"},{"id":"d","texte":"Le poème est une description scientifique des objets du monde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Ponge refuse d’**humaniser** les choses : il ne leur prête ni sentiments ni symboles."},{"cle":{"type":"zone","ids":["m7"]},"explication":"L’auteur rature **« triste »** : le galet ne ressent rien, et décrire est plus difficile que s’épancher."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Les **reprises** font du poème un processus ; sans vers ni rime, la **justesse** fait la poésie ; le « je » d’**ouvrier** nous place dans l’atelier ; refuser d’humaniser fait de la chose un **défi au langage**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Chez Ponge, le poème **rend compte de sa propre fabrication** : le brouillon devient une forme."}]$ex$::jsonb),
