  ('38309011-0b28-59be-9ba4-c96673792edb'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un résumé à annoter","competence":"analyser-texte","situation":"Un camarade a écrit un résumé de *La Reine Margot* pour ta fiche. Lis-le, puis vérifie ce que tu sais sur les personnages.","documents":[{"id":"res","type":"texte","genre":"article","titre":"Résumé du roman","blocs":["En août 1572, Marguerite de Valois, catholique, épouse Henri de Navarre, protestant.","Six jours plus tard éclate le massacre de la Saint-Barthélemy, ordonné par Catherine de Médicis et par Charles IX. Cette nuit-là, Margot sauve La Mole, un jeune gentilhomme blessé, dont elle devient la maîtresse.","Plus tard, Henri sauve Charles IX d’un sanglier : le roi lui garde de l’amitié. Mais un livre empoisonné destiné à Henri vient frapper un autre lecteur."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui opposent les mariés.","aide":"Cherche ce qui distingue leurs religions.","type":"zone","document":"res","multiple":true},{"enonce":"Pourquoi Charles IX garde-t-il de l’amitié à Henri de Navarre ?","aide":"Le résumé raconte un épisode de chasse.","type":"choix","options":[{"id":"a","texte":"Henri a sauvé sa sœur Margot de la prison"},{"id":"b","texte":"Henri l’a défendu contre les poisons de René"},{"id":"c","texte":"Henri l’a sauvé d’un sanglier lors d’une chasse"},{"id":"d","texte":"Henri a renoncé à sa foi protestante pour lui plaire"}],"multiple":false},{"enonce":"Relie chaque personnage à ce qu’il incarne.","aide":"Cherche, pour chacun, le trait de caractère dominant.","type":"association","gauche":[{"id":"g0","texte":"Catherine de Médicis"},{"id":"g1","texte":"Charles IX"},{"id":"g2","texte":"Le duc d’Alençon"},{"id":"g3","texte":"Margot"}],"droite":[{"id":"d0","texte":"La reine mère calculatrice, qui consulte astrologues et empoisonneurs"},{"id":"d1","texte":"Une reine libre et courageuse"},{"id":"d2","texte":"Un roi tourmenté, hanté par le massacre"},{"id":"d3","texte":"Un frère cadet jaloux et traître"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m11"]},"explication":"Margot est **catholique**, Henri de Navarre est **protestant** : le mariage de 1572 réunit deux camps."},{"cle":{"type":"choix","ids":["c"]},"explication":"Henri **sauve Charles IX d’un sanglier** : le roi lui garde de l’amitié."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"**Catherine** calcule, **Charles IX** est hanté, **Alençon** trahit, **Margot** est libre et courageuse."}]$ex$::jsonb),
