   $ex${"titre":"Violer l’Histoire, mais pas n’importe comment","competence":"argumenter","situation":"Deux élèves se demandent si Dumas « ment » en mêlant l’Histoire et la fiction. Lis leur échange et le tableau, puis tranche.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Dumas invente des amours à des gens qui ont vraiment existé : c’est de la triche."},{"qui":"Théo","texte":"Il mêle des faits attestés et des ressorts romanesques. Il ne prétend pas écrire un manuel."},{"qui":"Inès","texte":"Et ce qu’on retient du roman, c’est quoi ?"},{"qui":"Théo","texte":"L’image de la Saint-Barthélemy et de Catherine de Médicis : plus que les manuels."}]},{"id":"meth","type":"tableau","titre":"La méthode de Dumas","colonnes":["Dumas emprunte","À quoi"],"lignes":[["Des personnages réels","Margot, Henri de Navarre, Catherine de Médicis"],["Des événements attestés","Le mariage de 1572 et le massacre de la Saint-Barthélemy"],["Des ressorts romanesques","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne ce que Dumas ajoute à l’Histoire.","aide":"Théo oppose les faits attestés à des ressorts d’un autre genre.","type":"zone","document":"deb","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Quelle partie du roman relève de l’invention ?","type":"choix","options":[{"id":"a","texte":"Un récit scientifique des causes des guerres de religion"},{"id":"b","texte":"Les amours cachées, les secrets et les rebondissements d’un feuilleton"},{"id":"c","texte":"Une copie fidèle des lettres de Catherine de Médicis"},{"id":"d","texte":"Les procès-verbaux exacts de chaque conseil du roi"}],"multiple":false},{"enonce":"Range chaque élément : emprunté à l’Histoire, ou ajouté par le romancier ?","aide":"Un fait attesté existe hors du roman ; un ressort romanesque sert