  ('134d63f1-7a3e-51c6-896e-5d62ae13ac77'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un narrateur qui s’aveugle lui-même","competence":"analyser-texte","situation":"Lis une page de journal écrite pour l’exercice, à la manière du pasteur, puis demande-toi ce que le lecteur comprend avant celui qui écrit.","documents":[{"id":"page","type":"texte","genre":"recit","titre":"Une page du journal","blocs":["Je lui ai dit que la neige était un grand silence blanc où rien ne pouvait salir la terre ; elle a souri.","Amélie m’a reproché de passer mes soirées auprès de l’enfant. Sa jalousie est mesquine : je n’éprouve pour Gertrude que de la charité, une charité toute chrétienne."],"source":"Texte écrit pour l’exercice, à la manière du récit de Gide"},{"id":"lect","type":"tableau","titre":"Ce qu’il dit, ce que le lecteur comprend","colonnes":["Ce que dit le pasteur","Ce que comprend le lecteur"],"lignes":[["« Je n’éprouve que de la charité. »","?"],["« La jalousie d’Amélie est mesquine. »","Amélie voit juste : le pasteur est déjà épris"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel le pasteur justifie son attachement.","aide":"Il dit qu’il n’éprouve pas autre chose que ce sentiment chrétien.","type":"zone","document":"page","multiple":false},{"enonce":"Touche le verbe qui montre qu’il retire le mal du monde qu’il décrit.","aide":"Il décrit la neige comme un lieu où rien ne peut abîmer la terre.","type":"zone","document":"page","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Le second exemple du tableau t’indique le sens à prendre : le lecteur voit plus loin que le narrateur.","type":"choix","options":[{"id":"a","texte":"Il est tout à fait sincère et le lecteur le croit sur parole"},{"id":"b","texte":"Il appelle charité ce qui est en réalité du désir"},{"id":"c","texte":"Il cache volontairement ses sentiments pour tromper sa femme"},{"id":"d","texte":"Il ne parle jamais de Gertrude avec la moindre tendresse"}],"multiple":false},{"enonce":"Relie chaque procédé de Gide à son effet.","aide":"Chaque procédé joue sur l’écart entre ce que dit le pasteur et ce qu’il fait.","type":"association","gauche":[{"id":"g0","texte":"Le journal à la première personne"},{"id":"g1","texte":"Le titre « Symphonie pastorale »"},{"id":"g2","texte":"La cécité de Gertrude"},{"id":"g3","texte":"Les citations de saint Paul"}],"droite":[{"id":"d0","texte":"Il est ironique : c’est le pasteur qui ne voit rien"},{"id":"d1","texte":"Elle répond à l’aveuglement moral du pasteur"},{"id":"d2","texte":"Le lecteur comprend avant celui qui écrit"},{"id":"d3","texte":"Le pasteur se justifie par l’Écriture"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m46"]},"explication":"Le pasteur se justifie par la **charité** : il confond charité et désir."},{"cle":{"type":"zone","ids":["m16"]},"explication":"Le verbe **salir** dit ce qu’il écarte : le pasteur ne décrit qu’un monde sans tache, sans mal ni péché."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le lecteur comprend que le pasteur **appelle charité ce qui est du désir** : le narrateur est de bonne foi, mais non fiable."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"Le **journal** laisse le lecteur comprendre avant le narrateur ; le **titre** est ironique ; la **cécité** physique répond à l’aveuglement moral ; **saint Paul** sert de justification."}]$ex$::jsonb),
  ('6fef7b26-688b-51a2-9fbd-c1d494a8c309'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Belleville, un Goncourt et un pseudonyme","competence":"analyser-document","situation":"Tu prépares l’oral sur *La Vie devant soi*. Lis la fiche du livre, puis repère les personnages du roman.","documents":[{"id":"carte","type":"fiche","modele":"affiche","entete":"La Vie devant soi","sousTitre":"Émile Ajar","emoji":"🏙️","lignes":[{"texte":"Prix Goncourt","valeur":"1975","id":"z1"},{"texte":"Vrai nom de l’auteur","valeur":"Romain Gary"},{"texte":"Premier Goncourt de Gary","valeur":"1956, pour Les Racines du ciel"},{"texte":"Lieu","valeur":"Belleville","id":"z2"}],"pied":"Un auteur, deux noms","teinte":"violet"},{"id":"pers","type":"tableau","titre":"Quelques personnages","colonnes":["Personnage","Qui il est"],"lignes":[["Momo","Petit garçon arabe, narrateur du roman"],["Madame Rosa","?"],["Monsieur Hamil","Il vieillit et récite Victor Hugo"],["Le docteur Katz","Le médecin du quartier"]],"enteteLignes":true}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » pour Madame Rosa ?","aide":"Elle garde les enfants de prostituées au sixième étage.","type":"choix","options":[{"id":"a","texte":"Une institutrice du quartier qui prépare Momo à ses examens"},{"id":"b","texte":"Une voisine arabe qui vend des tapis sur le marché"},{"id":"c","texte":"Une infirmière de nuit qui soigne les vieillards de l’immeuble"},{"id":"d","texte":"Une ancienne prostituée juive, rescapée d’Auschwitz, qui garde des enfants"}],"multiple":false},{"enonce":"Touche la case qui décrit celui qui récite un grand auteur.","aide":"Cherche le nom d’un écrivain du XIXe siècle dans le tableau.","type":"zone","document":"pers","multiple":false},{"enonce":"Combien d’années séparent les deux prix Goncourt de Romain Gary ?","aide":"Soustrais les deux dates de la fiche.","type":"nombre","unite":"ans"},{"enonce":"Touche la ligne qui dit dans quel quartier se passe le roman.","aide":"C’est un quartier populaire de Paris.","type":"zone","document":"carte","multiple":false}]}$ex$::jsonb,
