  ('6fef7b26-688b-51a2-9fbd-c1d494a8c309'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le sixième sans ascenseur","competence":"analyser-texte","situation":"Momo raconte avec ses mots. Lis une page écrite pour l’exercice, à la manière de sa voix, puis suis ce que le cours dit du secret de Madame Rosa et de la fin du roman.","documents":[{"id":"page","type":"texte","genre":"recit","titre":"À la manière de Momo","blocs":["Chez nous c’est au sixième sans ascenseur et Madame Rosa elle monte les marches une à une en s’arrêtant à chaque palier pour dire que c’est la dernière fois. Moi je porte le cabas.","Elle a peur qu’on l’emmène à l’hôpital où on la branchera à des tuyaux jusqu’à la fin des temps, alors elle m’a demandé de ne jamais la laisser partir là-bas. On est descendus au sous-sol, dans son coin à elle, et je suis resté auprès d’elle."],"source":"Texte écrit pour l’exercice, à la manière de La Vie devant soi"},{"id":"secret","type":"tableau","titre":"Le secret de Madame Rosa","colonnes":["Le secret","Ce qui se passe"],"lignes":[["Le retour du père","Un homme sorti d’un asile vient réclamer son fils ; Rosa prétend l’avoir élevé dans la religion juive"],["La révélation","Momo apprend qu’il a quatorze ans, non dix : Rosa l’a rajeuni pour le garder"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que ressent Madame Rosa devant l’hôpital.","aide":"C’est le contraire du courage.","type":"zone","document":"page","multiple":false},{"enonce":"De combien d’années Madame Rosa a-t-elle rajeuni Momo ?","aide":"Compare l’âge que croyait Momo et son âge réel.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi Madame Rosa a-t-elle caché son âge à Momo ?","aide":"Le tableau l’explique dans la case « La révélation ».","type":"choix","options":[{"id":"a","texte":"Pour le garder auprès d’elle et l’empêcher d’être réclamé"},{"id":"b","texte":"Pour cacher qu’il est le fils de Monsieur Hamil"},{"id":"c","texte":"Pour obtenir plus d’argent des mères du quartier"},{"id":"d","texte":"Pour le protéger du service militaire qui approche"}],"multiple":false},{"enonce":"Remets dans l’ordre les derniers temps du roman.","aide":"La fin suit le déclin de Madame Rosa, jusqu’après sa mort.","type":"ordre","items":[{"id":"a","texte":"Momo l’aide à descendre au sous-sol"},{"id":"b","texte":"Il reste encore trois semaines auprès d’elle, avec du parfum"},{"id":"c","texte":"Il reste auprès d’elle jusqu’à sa mort"},{"id":"d","texte":"Madame Rosa s’affaiblit et perd la tête"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m39"]},"explication":"Madame Rosa a **peur** de l’hôpital : elle redoute l’acharnement thérapeutique."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"14 − 10 = **4 ans** : Rosa l’a rajeuni pour le garder auprès d’elle."},{"cle":{"type":"choix","ids":["a"]},"explication":"Rosa **l’a rajeuni pour le garder** : plus Momo est petit, moins on peut le lui reprendre."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"Rosa **s’affaiblit**, Momo l’aide à descendre au **sous-sol**, reste près d’elle **jusqu’à sa mort**, puis **trois semaines encore** avec du parfum."}]$ex$::jsonb),
  ('6fef7b26-688b-51a2-9fbd-c1d494a8c309'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Rire et pleurer, c’est le même métier","competence":"argumenter","situation":"Peut-on parler de choses graves avec la voix d’un enfant ? Lis un passage écrit pour l’exercice à la manière de Momo, puis un débat entre deux élèves.","documents":[{"id":"page","type":"texte","genre":"recit","titre":"À la manière de Momo","blocs":["Madame Rosa m’a demandé si j’avais peur. J’ai dit que non, parce que quand on a peur on n’a pas le temps de faire la soupe. Elle a ri et puis elle a pleuré, et c’était pareil. Chez les grands le rire et les larmes c’est le même métier, je crois."],"source":"Texte écrit pour l’exercice, à la manière de La Vie devant soi"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Zoé","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoé","texte":"Un enfant ne peut pas raconter des choses graves : le roman reste léger."},{"qui":"Malik","texte":"Au contraire : sa naïveté rend le terrible supportable, et le rend plus fort."},{"qui":"Zoé","texte":"Mais il parle un français fautif…"},{"qui":"Malik","texte":"Justement : humour et gravité se mêlent dans sa voix."}]}],"questions":[{"enonce":"Touche les deux verbes qui se mêlent chez Madame Rosa.","aide":"L’un dit la joie, l’autre la peine.","type":"zone","document":"page","multiple":true},{"enonce":"Touche le mot qui dit ce que la naïveté de l’enfant change au terrible.","aide":"Malik explique l’effet de la voix d’enfant sur ce qui est dur à entendre.","type":"zone","document":"deb","multiple":false},{"enonce":"Relie chaque procédé du roman à son effet.","aide":"Chaque procédé porte un thème du roman : le regard, la famille, la mort.","type":"association","gauche":[{"id":"g0","texte":"La voix de Momo en français fautif"},{"id":"g1","texte":"Le regard d’enfant"},{"id":"g2","texte":"Une Juive et un petit Arabe liés par l’amour"},{"id":"g3","texte":"Le refus de l’hôpital"}],"droite":[{"id":"d0","texte":"Humour et gravité mêlés"},{"id":"d1","texte":"La naïveté rend le terrible supportable"},{"id":"d2","texte":"Le droit de mourir dans la dignité"},{"id":"d3","texte":"Une famille choisie, contre tous les clivages"}]},{"enonce":"Quelle problématique le passage et le débat permettent-ils de défendre ?","aide":"Rappelle-toi la réponse de Malik à Zoé.","type":"choix","options":[{"id":"a","texte":"Le rire d’un enfant prouve que le drame n’est pas réel"},{"id":"b","texte":"La gravité d’un récit dépend toujours de la langue soutenue"},{"id":"c","texte":"Un narrateur enfant empêche le roman de traiter de sujets graves"},{"id":"d","texte":"Le regard naïf d’un enfant peut dire la gravité sans la lourdeur"}],"multiple":false}]}$ex$::jsonb,
